/**
 * The template toolkit shared by every game's code generator: the indentation-aware `code` tag,
 * seeded numbers, mod naming, effects parsed from the prompt and the feature list.
 */
import type { CategoryKey, CategoryMeta, CodeLanguage, Game, ModelId, ModFile } from "@/lib/cyrus/types";

export interface TemplateInput {
  game: Game;
  category: CategoryMeta;
  modName: string;
  prompt: string;
  model: ModelId;
  version: number;
}

/* ───────────── utilities ───────────── */

const EMPTY = "\u0000";

/**
 * Indentation-aware template tag: strips the common indent, re-indents multi-line
 * interpolations to the placeholder's column and drops lines whose only content was
 * an empty interpolation.
 */
export function code(strings: TemplateStringsArray, ...vals: unknown[]): string {
  let out = "";
  strings.forEach((s, i) => {
    out += s;
    if (i >= vals.length) return;
    const v = vals[i];
    let str = Array.isArray(v)
      ? v.filter((x) => x !== false && x != null && x !== "").map((x) => String(x).replace(/\n+$/, "")).join("\n")
      : v === false || v == null || v === ""
        ? ""
        : String(v).replace(/\n+$/, "");
    if (!str) str = EMPTY;
    const lineStart = out.slice(out.lastIndexOf("\n") + 1);
    const indent = lineStart.match(/^[ \t]*/)![0];
    out += str
      .split("\n")
      .map((l, j) => (j === 0 || !l ? l : indent + l))
      .join("\n");
  });
  const lines = out
    .replace(/^\n/, "")
    .split("\n")
    .filter((l) => l.trim() !== EMPTY)
    .map((l) => l.replaceAll(EMPTY, ""));
  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
  const min = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)![0].length));
  return (
    lines
      .map((l) => l.slice(Number.isFinite(min) ? min : 0).trimEnd())
      .join("\n")
      .replace(/\n{3,}/g, "\n\n") + "\n"
  );
}

export function hashStr(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

export function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function languageForPath(path: string): CodeLanguage {
  const ext = path.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "java":
      return "java";
    case "psc":
      return "papyrus";
    case "cs":
      return "csharp";
    case "lua":
      return "lua";
    case "glsl":
    case "fsh":
    case "vsh":
    case "fx":
      return "glsl";
    case "json":
      return "json";
    case "md":
      return "markdown";
    case "xml":
      return "xml";
    case "toml":
    case "properties":
    case "txt":
      return ext === "txt" ? "text" : "toml";
    default:
      return "text";
  }
}

export const file = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/* ───────────── identity & numbers ───────────── */

export function identity(modName: string) {
  const words = modName.replace(/[^A-Za-z0-9 ]+/g, " ").split(/\s+/).filter(Boolean);
  let cls = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  if (!cls) cls = "AstralMod";
  if (/^\d/.test(cls)) cls = `Cy${cls}`;
  const snake = words.join("_").toLowerCase() || "astral_mod";
  return { cls, snake: /^\d/.test(snake) ? `cy_${snake}` : snake, kebab: snake.replace(/_/g, "-") };
}

export function numbers(input: TemplateInput) {
  const rnd = mulberry32(hashStr(`${input.game.id}|${input.category.key}|${input.modName}|${input.version}`));
  const r = (a: number, b: number, d = 1) => Number((a + rnd() * (b - a)).toFixed(d));
  const i = (a: number, b: number) => Math.round(a + rnd() * (b - a));
  return {
    power: r(5, 14),
    cooldown: r(1.5, 8),
    radius: i(3, 9),
    duration: i(4, 12),
    chance: r(0.12, 0.4, 2),
    health: i(18, 90) * 10,
    speed: r(0.24, 0.42, 2),
    interval: i(2, 10),
    xp: i(12, 80),
    hue: i(0, 359),
    intensity: r(0.6, 1.4, 2),
    rnd,
  };
}

/* ───────────── intent: effects parsed from the prompt ───────────── */

export type EffectKey = "frost" | "fire" | "storm" | "blink" | "heal" | "poison" | "summon" | "flight" | "void" | "lunar" | "auto" | "neon";

export interface Effect {
  key: EffectKey;
  re: RegExp;
  label: string;
  java: string;
  particle: string;
  sound: string;
  papyrus: string;
  sv: string;
  tml: string;
  lua: string;
  tint: [number, number, number];
}

// TARGET / SOURCE are substituted per call site.
export const EFFECTS: Effect[] = [
  {
    key: "frost",
    re: /frost|ice|icy|freez|snow|cold|glacier|blizzard/,
    label: "Freezes and slows what it hits",
    java: "TARGET.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOWNESS, EFFECT_TICKS, 3));\nTARGET.setFrozenTicks(TARGET.getMinFreezeDamageTicks() + EFFECT_TICKS);",
    particle: "ParticleTypes.SNOWFLAKE",
    sound: "SoundEvents.BLOCK_GLASS_BREAK",
    papyrus: "FrostSlowSpell.Cast(SOURCE, TARGET)\nTARGET.DamageActorValue(\"Stamina\", Power)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.frost\", duration: EffectMillis, effects: new BuffEffects { Speed = { -2 } }));",
    tml: "TARGET.AddBuff(BuffID.Frostburn2, EffectTicks);\nTARGET.velocity *= 0.35f;",
    lua: "StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Cripple\")",
    tint: [0.62, 0.86, 1.0],
  },
  {
    key: "fire",
    re: /fire|flame|burn|ember|lava|inferno|blaze/,
    label: "Sets targets ablaze",
    java: "TARGET.setOnFireFor(EFFECT_TICKS / 20f);",
    particle: "ParticleTypes.FLAME",
    sound: "SoundEvents.ENTITY_BLAZE_SHOOT",
    papyrus: "FireCloakSpell.Cast(SOURCE, TARGET)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.ember\", duration: EffectMillis, effects: new BuffEffects { Attack = { 3 } }));",
    tml: "TARGET.AddBuff(BuffID.OnFire3, EffectTicks);",
    lua: "StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Burning\")",
    tint: [1.0, 0.55, 0.3],
  },
  {
    key: "storm",
    re: /lightning|storm|thunder|shock|electric|spark/,
    label: "Calls down chain lightning",
    java: "LightningEntity bolt = EntityType.LIGHTNING_BOLT.create(WORLD);\nif (bolt != null) {\n    bolt.refreshPositionAfterTeleport(TARGET.getPos());\n    WORLD.spawnEntity(bolt);\n}",
    particle: "ParticleTypes.ELECTRIC_SPARK",
    sound: "SoundEvents.ENTITY_LIGHTNING_BOLT_THUNDER",
    papyrus: "ChainLightningSpell.Cast(SOURCE, TARGET)",
    sv: "Utility.drawLightningBolt(Game1.player.Position, Game1.currentLocation);",
    tml: "Projectile.NewProjectile(SOURCE_SRC, TARGET.Center - new Vector2(0, 600), new Vector2(0, 18), ProjectileID.CultistBossLightningOrbArc, Power, 2f);",
    lua: "StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Electrocuted\")",
    tint: [0.7, 0.75, 1.0],
  },
  {
    key: "blink",
    re: /teleport|blink|ender|warp|portal|phase/,
    label: "Blinks the wielder through space",
    java: "SOURCE.requestTeleport(TARGET.getX(), TARGET.getY(), TARGET.getZ());",
    particle: "ParticleTypes.PORTAL",
    sound: "SoundEvents.ENTITY_ENDERMAN_TELEPORT",
    papyrus: "SOURCE.MoveTo(TARGET, 0.0, 120.0, 0.0)",
    sv: "Game1.player.Position = Game1.player.Position + Game1.player.FacingDirectionVector() * 64 * 3;",
    tml: "SOURCE.Teleport(TARGET.Center - new Vector2(0, 48), TeleportationStyleID.RodOfDiscord);",
    lua: "Game.GetTeleportationFacility():Teleport(SOURCE, TARGET:GetWorldPosition(), EulerAngles.new(0, 0, 0))",
    tint: [0.75, 0.45, 1.0],
  },
  {
    key: "heal",
    re: /heal|regen|restore|life|vampir|leech/,
    label: "Heals the wielder on every hit",
    java: "SOURCE.heal(POWER * 0.25F);",
    particle: "ParticleTypes.HEART",
    sound: "SoundEvents.ENTITY_PLAYER_LEVELUP",
    papyrus: "SOURCE.RestoreActorValue(\"Health\", Power * 0.5)",
    sv: "Game1.player.health = Math.Min(Game1.player.maxHealth, Game1.player.health + (int)Power);",
    tml: "SOURCE.Heal((int)(Power * 0.2f));",
    lua: "Game.GetStatPoolsSystem():RequestChangingStatPoolValue(SOURCE:GetEntityID(), gamedataStatPoolType.Health, Power, nil, false, false)",
    tint: [0.6, 1.0, 0.7],
  },
  {
    key: "poison",
    re: /poison|venom|toxic|acid|plague/,
    label: "Poisons on hit",
    java: "TARGET.addStatusEffect(new StatusEffectInstance(StatusEffects.POISON, EFFECT_TICKS, 1));",
    particle: "ParticleTypes.ITEM_SLIME",
    sound: "SoundEvents.ENTITY_SLIME_SQUISH",
    papyrus: "PoisonSpell.Cast(SOURCE, TARGET)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.venom\", duration: EffectMillis, effects: new BuffEffects { Defense = { -1 } }));",
    tml: "TARGET.AddBuff(BuffID.Venom, EffectTicks);",
    lua: "StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Poisoned\")",
    tint: [0.6, 1.0, 0.45],
  },
