    particle: "ParticleTypes.SOUL",
    sound: "SoundEvents.ENTITY_EVOKER_CAST_SPELL",
    papyrus: "SOURCE.PlaceAtMe(SummonedEcho, 1)",
    sv: "Game1.currentLocation.characters.Add(new Monsters.Bat(Game1.player.Position + new Vector2(64, 0)));",
    tml: "NPC.NewNPC(SOURCE_SRC, (int)TARGET.Center.X, (int)TARGET.Center.Y, ModContent.NPCType<EchoMinion>());",
    lua: "Game.GetPreventionSpawnSystem():RequestUnitSpawn(\"Character.cyrus_echo\", TARGET:GetWorldTransform())",
    tint: [0.55, 0.9, 1.0],
  },
  {
    key: "flight",
    re: /fly|flying|flight|hover|glide|wing|dragon/,
    label: "Grants short bursts of flight",
    java: "SOURCE.addStatusEffect(new StatusEffectInstance(StatusEffects.SLOW_FALLING, EFFECT_TICKS, 0));\nSOURCE.addVelocity(0, 0.8, 0);",
    particle: "ParticleTypes.CLOUD",
    sound: "SoundEvents.ENTITY_PHANTOM_FLAP",
    papyrus: "SOURCE.ModActorValue(\"SpeedMult\", 30.0)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.gale\", duration: EffectMillis, effects: new BuffEffects { Speed = { 2 } }));",
    tml: "SOURCE.wingTime = SOURCE.wingTimeMax;\nSOURCE.velocity.Y -= 6f;",
    lua: "SOURCE:GetMovePolicesComponent():SetGravityMultiplier(0.35)",
    tint: [0.85, 0.95, 1.0],
  },
  {
    key: "void",
    re: /shadow|dark|void|night|eclipse|abyss|wither/,
    label: "Drains targets with void energy",
    java: "TARGET.addStatusEffect(new StatusEffectInstance(StatusEffects.WITHER, EFFECT_TICKS, 1));\nTARGET.addStatusEffect(new StatusEffectInstance(StatusEffects.DARKNESS, EFFECT_TICKS, 0));",
