    papyrus: "TARGET.DamageActorValue(\"Magicka\", Power * 2.0)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.void\", duration: EffectMillis, effects: new BuffEffects { MagneticRadius = { 64 } }));",
