    lua: "StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Blind\")",
    tint: [0.55, 0.35, 0.9],
  },
  {
    key: "lunar",
    re: /moon|lunar|star|cosmic|nebula|glow|celestial|aurora/,
    label: "Grows stronger under moonlight",
    java: "if (WORLD.isNight()) {\n    TARGET.addStatusEffect(new StatusEffectInstance(StatusEffects.GLOWING, EFFECT_TICKS, 0));\n    TARGET.damage(WORLD.getDamageSources().magic(), POWER * 0.5F);\n}",
    particle: "ParticleTypes.END_ROD",
    sound: "SoundEvents.BLOCK_AMETHYST_BLOCK_CHIME",
    papyrus: "If GameHour.GetValue() > 20.0 || GameHour.GetValue() < 5.0\n    AuroraShader.Play(TARGET, 3.0)\nEndIf",
    sv: "if (Game1.timeOfDay >= 2000) Game1.player.applyBuff(new Buff(\"cyrus.lunar\", duration: EffectMillis, effects: new BuffEffects { LuckLevel = { 2 } }));",
    tml: "if (!Main.dayTime) TARGET.AddBuff(BuffID.Daybreak, EffectTicks);",
    lua: "if Game.GetTimeSystem():GetGameTime():Hours() >= 21 then StatusEffectHelper.ApplyStatusEffect(TARGET, \"BaseStatusEffect.Stun\") end",
    tint: [0.8, 0.8, 1.0],
  },
  {
    key: "auto",
    re: /auto|harvest|farm|collect|sort|craft/,
    label: "Automates the busywork",
    java: "SOURCE.addStatusEffect(new StatusEffectInstance(StatusEffects.HASTE, EFFECT_TICKS, 1));",
    particle: "ParticleTypes.HAPPY_VILLAGER",
    sound: "SoundEvents.BLOCK_NOTE_BLOCK_CHIME",
    papyrus: "SOURCE.ModActorValue(\"CarryWeight\", 25.0)",
    sv: "Game1.player.applyBuff(new Buff(\"cyrus.harvest\", duration: EffectMillis, effects: new BuffEffects { FarmingLevel = { 2 } }));",
    tml: "SOURCE.pickSpeed -= 0.25f;",
    lua: "Game.GetStatsSystem():AddModifier(SOURCE:GetEntityID(), RPGManager.CreateStatModifier(gamedataStatType.CarryCapacity, gameStatModifierType.Additive, 50))",
    tint: [0.75, 1.0, 0.55],
  },
  {
    key: "neon",
    re: /neon|hud|ram|cyber|hack|chrome|netrun|quickhack/,
    label: "Reacts to your cyberware",
    java: "SOURCE.addStatusEffect(new StatusEffectInstance(StatusEffects.NIGHT_VISION, EFFECT_TICKS, 0));",
    particle: "ParticleTypes.GLOW",
    sound: "SoundEvents.BLOCK_BEACON_ACTIVATE",
