export const DEFAULT_EFFECTS: Record<CategoryKey, EffectKey[]> = {
  weapons: ["storm", "fire", "frost"],
  creatures: ["void", "poison", "summon"],
  worlds: ["lunar", "frost"],
  mechanics: ["auto", "neon"],
  shaders: ["lunar", "neon"],
  magic: ["storm", "lunar", "frost"],
  quests: ["lunar", "void"],
  interface: ["neon", "auto"],
  audio: ["lunar", "neon"],
  vehicles: ["flight", "neon"],
  items: ["auto", "heal"],
  characters: ["heal", "lunar"],
};

export function effectsFor(input: TemplateInput): Effect[] {
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  const hits = EFFECTS.filter((e) => e.re.test(text)).slice(0, 2);
  if (hits.length) return hits;
  const pool = DEFAULT_EFFECTS[input.category.key];
  const key = pool[hashStr(input.modName) % pool.length];
  return [EFFECTS.find((e) => e.key === key)!];
}

export const sub = (s: string, target: string, source: string, extra: Record<string, string> = {}) => {
  let out = s.replaceAll("TARGET", target).replaceAll("SOURCE_SRC", extra.SOURCE_SRC ?? "source").replaceAll("SOURCE", source);
  for (const [k, v] of Object.entries(extra)) out = out.replaceAll(k, v);
  return out;
};

export type Arch = "item" | "entity" | "world" | "system" | "visual";
export const ARCH: Record<CategoryKey, Arch> = {
  weapons: "item",
  items: "item",
