import { TERRARIA_PINNED_VERSION, terrariaKnown } from "../lib/terraria-image";
import { mirroredEntry, terrariaMirrorUrl } from "../lib/terraria-mirror";
import type { UpdateTarget } from "./terraria-update";

/** A version's image facts: the verified table first, else what the mirror sweep recorded. Null = not available. */
export async function resolveTerrariaTarget(version: string): Promise<UpdateTarget | null> {
  if (!/^\d+\.\d+\.\d+$/.test(version)) return null;
  const k = terrariaKnown(version);
  const m = await mirroredEntry(version).catch(() => null);
  if (!k && !m) return null;
  let mirror: UpdateTarget["mirror"] = null;
  if (m?.mirror) {
    try {
      mirror = { url: terrariaMirrorUrl(version), sha256: m.mirror.sha256 };
    } catch {
      mirror = null; // no URL secret in this process: registry fallback
    }
  }
  const imageId = k?.imageId ?? m?.mirror?.imageId ?? null;
  if (!imageId) return null; // never run an image we cannot identify
  return { tshock: version, terraria: k?.terraria ?? m!.terraria, imageId, indexDigest: k?.indexDigest ?? null, mirror };
}

/**
 * Provision / reinstall hook (like worker/mcjar-pin.ts#mcJarPinForSetup): which image tag a fresh
 * Terraria install runs and whether our mirror can supply it. Never throws; null = not Terraria.
 */
export async function terrariaSetupPlan(server: { osTemplate?: { family?: string | null } | null; gameConfig?: unknown }): Promise<{ version: string; mirror: { url: string; sha256: string } | null } | null> {
  if (server.osTemplate?.family !== "terraria") return null;
  const v = (server.gameConfig as Record<string, unknown> | null)?.["tshock-version"];
  const version = typeof v === "string" && /^\d+\.\d+\.\d+$/.test(v) ? v : TERRARIA_PINNED_VERSION;
  try {
    const t = await resolveTerrariaTarget(version);
    return { version, mirror: t?.mirror ?? null };
  } catch {
    return { version, mirror: null };
  }
}
