export const TERRARIA_LEGACY_IMAGE_RE = /(^|\/)ryshe\/terraria(:|@|$)/;
export const TERRARIA_LEGACY_VERSIONS = { tshock: "6.1.0", terraria: "1.4.5.6" };

export function terrariaKnown(version: string): TerrariaKnownVersion | null {
  return TERRARIA_KNOWN_VERSIONS.find((v) => v.tshock === version) ?? null;
}
export const TERRARIA_PINNED = (): TerrariaKnownVersion => {
  const k = terrariaKnown(TERRARIA_PINNED_VERSION);
  if (!k) throw new Error(`TERRARIA_PINNED_VERSION ${TERRARIA_PINNED_VERSION} has no row in TERRARIA_KNOWN_VERSIONS`);
  return k;
};

/** Image reference for a release: always an explicit version tag, never `latest`. */
export function terrariaImageRef(version: string): string {
  return `${TERRARIA_IMAGE_REPO}:${version}`;
}
/** Immutable reference used for registry pulls when the mirror is not used. */
export function terrariaImageByDigest(k: TerrariaKnownVersion): string {
  return `${TERRARIA_IMAGE_REPO}@${k.indexDigest}`;
}
export const TERRARIA_IMAGE = terrariaImageRef(TERRARIA_PINNED_VERSION);

export const isLegacyTerrariaImage = (image: string): boolean => TERRARIA_LEGACY_IMAGE_RE.test(image);
export const isOfficialTerrariaImage = (image: string): boolean => image.startsWith(`${TERRARIA_IMAGE_REPO}:`) || image.startsWith(`${TERRARIA_IMAGE_REPO}@`);

/** The TShock version in an official image reference ("…/tshock:6.2.1" -> "6.2.1"), else null. */
export function versionFromImage(image: string): string | null {
  const m = new RegExp(`^${TERRARIA_IMAGE_REPO.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")}:(\\d+\\.\\d+\\.\\d+)(?:@|$)`).exec(image);
  return m ? m[1] : null;
}

// ---------------------------------------------------------------------------
// Version comparison and the "never take a world backwards" rule
// ---------------------------------------------------------------------------

export function compareDotted(a: string, b: string): number {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] ?? 0) - (pb[i] ?? 0);
    if (d) return d < 0 ? -1 : 1;
  }
  return 0;
}

/** Is `to` (TShock version) a legal move from a server on `from`? Same-or-newer Terraria only. */
export function updateDirection(from: { tshock: string; terraria: string }, to: { tshock: string; terraria: string }): "upgrade" | "same" | "downgrade" {
  const t = compareDotted(to.terraria, from.terraria);
  if (t < 0) return "downgrade";
  const s = compareDotted(to.tshock, from.tshock);
  if (t === 0 && s === 0) return "same";
  if (t === 0 && s < 0) return "downgrade";
  return "upgrade";
}

