/* ═════════════════════════ tModLoader content ═════════════════════════ */

interface Tml {
  input: TemplateInput;
  n: Nums;
  t: Tuning;
  fx: EffectKey[];
  cls: string;
  mod: string; // internal mod name = folder name = root namespace
  model: string;
  config: boolean; // a ModConfig file ships (saka/yakko); katara gets constants
  side: "Both" | "Client";
  lang: { section: string; key: string; display: string; tooltip?: string }[];
  extraDocs: string[];
}

function tuningBlock(c: Tml): string {
  if (c.config) return `private static ${c.cls}Config Tuning => ModContent.GetInstance<${c.cls}Config>();`;
  return code`
    private static class Tuning
    {
        public const float Power = ${f1(c.t.power)};
        public const int EffectTicks = ${c.t.effectTicks};
        public const int RadiusTiles = ${c.t.radiusTiles};
        public const float Chance = ${f1(c.t.chance)};
        public const int CooldownSeconds = ${c.t.cooldownSeconds};
    }`;
}

const header = (c: Tml) =>
  code`
    // ${c.input.modName}: made with Cyrus (${c.model}), v${c.input.version}.
    // Target: tModLoader ${TML_TARGET.month} stable (Terraria ${TML_TARGET.terraria}). Placeholder art comes from the player's own game;
    // drop a PNG with the class name next to this file and delete the Texture line to use your own.`;

const hitFx = (c: Tml) => c.fx.map(tmlOnHitNpc);
const dustLine = (c: Tml, where: string) => `Dust.NewDust(${where}.position, ${where}.width, ${where}.height, ${DUST[c.fx[0]]});`;

const MELEE_ART: [RegExp, string][] = [
  [/frost|ice|snow|cold|glacier|blizzard/, "Frostbrand"],
  [/fire|flame|ember|lava|inferno|blaze/, "FieryGreatsword"],
