const BOW_ART: [RegExp, string][] = [[/frost|ice/, "IceBow"], [/fire|lava|hell/, "MoltenFury"], [/lunar|star|cosmic/, "DaedalusStormbow"], [/storm|lightning/, "Tsunami"]];
const GUN_ART: [RegExp, string][] = [[/frost|ice/, "SnowballCannon"], [/storm|lightning|electric/, "Megashark"], [/void|shadow/, "Uzi"]];
const STAFF_ART: [RegExp, string][] = [[/frost|ice/, "FrostStaff"], [/fire|flame|lava/, "WandofSparking"], [/void|shadow/, "ShadowbeamStaff"], [/poison|venom/, "PoisonStaff"], [/lunar|star|cosmic/, "StarfuryStaff_UNUSED"], [/storm|lightning/, "SkyFracture"]];
const BOLT: Record<EffectKey, string> = {
