type WeaponKind = "sword" | "yoyo" | "bow" | "gun" | "magic";
function weaponKind(input: TemplateInput): WeaponKind {
  const t = textOf(input);
  if (/\byoyos?\b/.test(t)) return "yoyo";
  if (/\b(bows?|longbow|crossbow|arrows?)\b/.test(t)) return "bow";
  if (/\b(guns?|rifle|pistol|blaster|shotgun|launcher|cannon|minigun)\b/.test(t)) return "gun";
  if (input.category.key === "magic" || /\b(staffs?|wands?|tome|spell|scepter|rod)\b/.test(t)) return "magic";
  return "sword";
}

function tmlWeapon(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const kind = weaponKind(input);
  const t = textOf(input);
  const dmg = Math.round(n.power * (kind === "magic" ? 4.5 : 6));
  const use = Math.max(10, Math.round(n.cooldown * 5));
  const rare = n.power > 10 ? "ItemRarityID.Lime" : "ItemRarityID.Pink";
  const hard = /hardmode|hard mode|endgame|late game|post[- ]?moon/.test(t) || n.power > 9;
  const recipe = hard
    ? code`
        CreateRecipe()
            .AddIngredient(ItemID.HallowedBar, ${n.radius + 6})
            .AddIngredient(ItemID.SoulofMight, ${n.interval + 2})
            .AddTile(TileID.MythrilAnvil)
            .Register();`
    : code`
        CreateRecipe()
            .AddIngredient(ItemID.${c.fx[0] === "frost" ? "IceBlock" : c.fx[0] === "fire" ? "HellstoneBar" : "FallenStar"}, ${n.radius + 4})
            .AddRecipeGroup(RecipeGroupID.IronBar, ${n.interval + 3})
            .AddTile(TileID.Anvils)
            .Register();`;
  c.lang.push({ section: "Items", key: cls, display: input.modName, tooltip: clean(deriveFeatures(input).slice(0, 2).join("\n")) });

  if (kind === "sword") {
    const art = pick(MELEE_ART, t, "Muramasa");
    return {
      main: file(
        `Content/Items/${cls}.cs`,
        code`
          using Microsoft.Xna.Framework;
          using Terraria;
          using Terraria.ID;
          using Terraria.ModLoader;

          namespace ${mod}.Content.Items
          {
              ${header(c)}
              public class ${cls} : ModItem
              {
                  public override string Texture => $"Terraria/Images/Item_{ItemID.${art}}";
                  ${tuningBlock(c)}

                  public override void SetDefaults() {
                      Item.width = 40;
                      Item.height = 40;
                      Item.useStyle = ItemUseStyleID.Swing;
                      Item.useTime = ${use};
                      Item.useAnimation = ${use};
                      Item.autoReuse = true;
                      Item.DamageType = DamageClass.Melee;
                      Item.damage = ${dmg};
                      Item.knockBack = ${f1(n.power / 2)};
                      Item.crit = 6;
                      Item.value = Item.sellPrice(gold: ${Math.max(1, Math.round(n.power))});
                      Item.rare = ${rare};
                      Item.UseSound = SoundID.Item1;
                  }

                  public override void MeleeEffects(Player player, Rectangle hitbox) {
                      if (Main.rand.NextBool(3))
                          Dust.NewDust(new Vector2(hitbox.X, hitbox.Y), hitbox.Width, hitbox.Height, ${DUST[c.fx[0]]});
                  }

                  public override void OnHitNPC(Player player, NPC target, NPC.HitInfo hit, int damageDone) {
                      ${hitFx(c)}
                  }

                  public override void AddRecipes() {
                      ${recipe}
                  }
              }
          }`,
      ),
    };
  }

  // Everything else fires our own projectile, so on-hit effects belong to the projectile.
  const projBase =
    kind === "yoyo" ? pick(YOYO_ART, t, "Code1") : kind === "bow" ? "WoodenArrowFriendly" : kind === "gun" ? "Bullet" : BOLT[c.fx[0]];
  const itemArt =
    kind === "yoyo" ? pick(YOYO_ART, t, "Code1") : kind === "bow" ? pick(BOW_ART, t, "PlatinumBow") : kind === "gun" ? pick(GUN_ART, t, "Handgun") : pick(STAFF_SAFE, t, "AmethystStaff");
  const itemDefaults: Record<Exclude<WeaponKind, "sword">, string> = {
    yoyo: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = 25;
      Item.useAnimation = 25;
      Item.noMelee = true;
      Item.noUseGraphic = true;
      Item.channel = true;
      Item.DamageType = DamageClass.MeleeNoSpeed;
      Item.UseSound = SoundID.Item1;
      Item.shoot = ModContent.ProjectileType<${cls}Projectile>();
      Item.shootSpeed = 16f;`,
    bow: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${use};
      Item.useAnimation = ${use};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Ranged;
      Item.useAmmo = AmmoID.Arrow;
      Item.UseSound = SoundID.Item5;
      Item.shoot = ProjectileID.PurificationPowder; // replaced by the ammo, then by our arrow in ModifyShootStats
      Item.shootSpeed = 11f;`,
    gun: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${Math.max(6, Math.round(use / 2))};
      Item.useAnimation = ${Math.max(6, Math.round(use / 2))};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Ranged;
      Item.useAmmo = AmmoID.Bullet;
      Item.UseSound = SoundID.Item11;
      Item.shoot = ProjectileID.PurificationPowder;
      Item.shootSpeed = 14f;`,
    magic: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${use};
      Item.useAnimation = ${use};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Magic;
      Item.mana = ${Math.max(4, Math.round(n.power))};
      Item.UseSound = SoundID.Item20;
      Item.shoot = ModContent.ProjectileType<${cls}Projectile>();
      Item.shootSpeed = 11f;`,
  };
  if (kind === "magic") itemDefaults.magic += "Item.staff[Type] = true;\n".replace(/^/, "");
  const ammoSwap =
    kind === "bow" || kind === "gun"
      ? code`
          public override void ModifyShootStats(Player player, ref Vector2 position, ref Vector2 velocity, ref int type, ref int damage, ref float knockback) {
              // Any ${kind === "bow" ? "arrow" : "bullet"} the player loads becomes this weapon's own shot (ammo damage still counts).
              type = ModContent.ProjectileType<${cls}Projectile>();
          }`
      : "";
  const projDefaults =
    kind === "yoyo"
      ? code`
          Projectile.width = 16;
          Projectile.height = 16;
          Projectile.aiStyle = ProjAIStyleID.Yoyo;
          Projectile.friendly = true;
          Projectile.DamageType = DamageClass.MeleeNoSpeed;
          Projectile.penetrate = -1;`
      : code`
          Projectile.CloneDefaults(ProjectileID.${projBase});
          AIType = ProjectileID.${projBase};
          Projectile.friendly = true;
          Projectile.hostile = false;
          Projectile.DamageType = DamageClass.${kind === "magic" ? "Magic" : "Ranged"};`;
  const projStatic =
    kind === "yoyo"
      ? code`
          public override void SetStaticDefaults() {
              ProjectileID.Sets.YoyosLifeTimeMultiplier[Type] = ${f1(3 + n.intensity)};
              ProjectileID.Sets.YoyosMaximumRange[Type] = ${200 + n.radius * 20}f;
              ProjectileID.Sets.YoyosTopSpeed[Type] = ${f1(11 + n.speed * 10)};
          }`
      : "";
  return {
    main: file(
      `Content/Items/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Items
        {
            ${header(c)}
            public class ${cls} : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.${itemArt}}";

                public override void SetStaticDefaults() {
                    ${kind === "yoyo" ? "ItemID.Sets.Yoyo[Type] = true;\nItemID.Sets.GamepadExtraRange[Type] = 15;" : kind === "magic" ? "Item.staff[Type] = true; // hold it like a staff" : "ItemID.Sets.ShimmerTransformToItem[Type] = ItemID.Musket;"}
                }

                public override void SetDefaults() {
                    Item.width = 32;
                    Item.height = 32;
                    Item.damage = ${dmg};
                    Item.knockBack = ${f1(n.power / 3)};
                    Item.value = Item.sellPrice(gold: ${Math.max(1, Math.round(n.power))});
                    Item.rare = ${rare};
                    ${itemDefaults[kind].replace("Item.staff[Type] = true;\n", "")}
                }

                ${ammoSwap}

                public override void AddRecipes() {
                    ${recipe}
                }
            }

            public class ${cls}Projectile : ModProjectile
            {
                public override string Texture => $"Terraria/Images/Projectile_{ProjectileID.${projBase}}";
                ${tuningBlock(c)}

                ${projStatic}

                public override void SetDefaults() {
                    ${projDefaults}
                }

                public override void AI() {
                    if (Main.rand.NextBool(4))
                        ${dustLine(c, "Projectile")}
                    Lighting.AddLight(Projectile.Center, ${c.input.game ? tint(c.fx[0]) : "0.5f, 0.5f, 0.5f"});
                }

                public override void OnHitNPC(NPC target, NPC.HitInfo hit, int damageDone) {
                    Player player = Main.player[Projectile.owner];
                    ${hitFx(c)}
                }
            }
        }`,
    ),
  };
}

const TINT: Record<EffectKey, [number, number, number]> = {
  frost: [0.4, 0.7, 1],
  fire: [1, 0.55, 0.2],
  storm: [0.6, 0.7, 1],
  blink: [0.7, 0.4, 1],
  heal: [0.4, 1, 0.5],
  poison: [0.5, 1, 0.3],
  summon: [0.5, 0.9, 1],
  flight: [0.85, 0.95, 1],
  void: [0.55, 0.3, 0.9],
  lunar: [0.75, 0.8, 1],
  auto: [1, 0.85, 0.4],
  neon: [1, 0.4, 0.85],
};
const tint = (e: EffectKey) => TINT[e].map(f1).join(", ");

function tmlAccessory(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const t = textOf(input);
  const art = pick(ACCESSORY_ART, t, "CelestialStone");
  const lines: string[] = [];
  if (/gravity|ceiling|flip/.test(t)) lines.push("player.gravControl = true; // flip gravity with Up, like the Gravity Globe");
  if (/boots|run|speed|sprint|dash/.test(t)) lines.push(`player.accRunSpeed = System.Math.Max(player.accRunSpeed, ${f1(5 + n.speed * 4)});`, `player.moveSpeed += ${f1(n.speed / 2)};`);
  if (/fall|boots|gravity/.test(t)) lines.push("player.noFallDmg = true;");
  if (/compass|biome|explor|map|find|locat/.test(t)) lines.push("player.accCompass = 1;", "player.accDepthMeter = 1;", "player.findTreasure = true; // spelunker glow on ores and chests");
  if (/wing|fly|flight|glide/.test(t)) lines.push("player.slowFall = true;", `player.jumpSpeedBoost += ${f1(1 + n.speed * 2)};`);
  if (/shield|guard|defen/.test(t)) lines.push(`player.statDefense += ${Math.round(n.power / 2) + 2};`, "player.noKnockback = true;");
  if (/ring|regen|heal|life/.test(t)) lines.push(`player.lifeRegen += ${Math.round(n.power / 3) + 1};`);
  if (/charm|amulet|necklace|luck/.test(t)) lines.push(`player.GetArmorPenetration(DamageClass.Generic) += ${Math.round(n.power / 2)};`);
  if (!lines.length) lines.push(`player.GetDamage(DamageClass.Generic) += ${f1(n.power / 100)};`, `player.moveSpeed += ${f1(n.speed / 3)};`);
  c.lang.push({ section: "Items", key: cls, display: input.modName, tooltip: clean(deriveFeatures(input).slice(0, 2).join("\n")) });
  return {
    main: file(
      `Content/Items/${cls}.cs`,
      code`
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Items
        {
            ${header(c)}
            public class ${cls} : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.${art}}";
                ${tuningBlock(c)}

                public override void SetDefaults() {
                    Item.width = 28;
                    Item.height = 28;
                    Item.accessory = true;
                    Item.value = Item.sellPrice(gold: ${Math.max(1, Math.round(n.power / 2))});
                    Item.rare = ItemRarityID.${n.power > 10 ? "LightPurple" : "Orange"};
                }

                public override void UpdateAccessory(Player player, bool hideVisual) {
                    ${lines}
                    if (!hideVisual && Main.rand.NextBool(12))
                        Dust.NewDust(player.position, player.width, player.height, ${DUST[c.fx[0]]});
                }

                public override void AddRecipes() {
                    CreateRecipe()
                        .AddIngredient(ItemID.${art}, 1)
                        .AddIngredient(ItemID.SoulofLight, ${n.interval + 3})
                        .AddTile(TileID.TinkerersWorkbench)
                        .Register();
                }
            }
        }`,
    ),
  };
}

const ENEMY_BASE: [RegExp, string][] = [
  [/slime|ooze|gel|blob/, "BlueSlime"],
  [/bat\b|bats\b/, "CaveBat"],
  [/moth|eye|wraith|ghost|spirit|fly|flying|wing/, "DemonEye"],
  [/skeleton|bone|undead/, "Skeleton"],
];
const ENEMY_DROP: Record<EffectKey, string> = {
  frost: "FrostCore",
  fire: "LivingFireBlock",
  storm: "FallenStar",
  blink: "SoulofLight",
  heal: "LifeCrystal",
  poison: "Stinger",
  summon: "SoulofNight",
  flight: "Feather",
  void: "SoulofNight",
  lunar: "FallenStar",
  auto: "GoldCoin",
  neon: "PixieDust",
};

function tmlEnemy(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const t = textOf(input);
  const base = pick(ENEMY_BASE, t, "Zombie");
  const hard = /hardmode|hard mode|late game|endgame/.test(t);
  const spawn =
    base === "CaveBat" || /cave|underground|cavern|deep/.test(t)
      ? "SpawnCondition.Cavern.Chance"
      : base === "BlueSlime"
        ? "SpawnCondition.OverworldDaySlime.Chance"
        : "SpawnCondition.OverworldNightMonster.Chance";
  const splits = c.fx.includes("summon") || /split|hive|swarm|clone/.test(t);
  c.lang.push({ section: "NPCs", key: cls, display: input.modName });
  return {
    main: file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Terraria;
        using Terraria.GameContent.ItemDropRules;
        using Terraria.ID;
        using Terraria.ModLoader;
        using Terraria.ModLoader.Utilities;

        namespace ${mod}.Content.NPCs
        {
            ${header(c)}
            public class ${cls} : ModNPC
            {
                public override string Texture => $"Terraria/Images/NPC_{NPCID.${base}}";
                ${tuningBlock(c)}

                public override void SetStaticDefaults() {
                    Main.npcFrameCount[Type] = Main.npcFrameCount[NPCID.${base}];
                }

                public override void SetDefaults() {
                    NPC.CloneDefaults(NPCID.${base}); // size, sounds and AI style of the base enemy
                    NPC.lifeMax = ${Math.round(n.health / (hard ? 2 : 5))};
                    NPC.damage = ${Math.round(n.power * (hard ? 6 : 3))};
                    NPC.defense = ${Math.round(n.power * (hard ? 2 : 1))};
                    NPC.value = ${Math.round(n.xp * 10)}f;
                    AIType = NPCID.${base};
                    AnimationType = NPCID.${base};
                    NPC.color = new Microsoft.Xna.Framework.Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                }

                public override float SpawnChance(NPCSpawnInfo spawnInfo) {
                    ${hard ? "if (!Main.hardMode)\n    return 0f;" : ""}
                    return ${spawn} * 0.15f;
                }

                public override void OnHitPlayer(Player target, Player.HurtInfo hurtInfo) {
                    ${c.fx.map((e) => `target.AddBuff(${TML_ON_HIT_PLAYER[e]}, Tuning.EffectTicks / 2);`)}
                }

                public override void HitEffect(NPC.HitInfo hit) {
                    for (int i = 0; i < 4; i++)
                        ${dustLine(c, "NPC")}
                }

                ${
                  splits
                    ? code`
                      public override void OnKill() {
                          // Splits on death. Only the server (or single player) spawns enemies; the game syncs them.
                          if (Main.netMode == NetmodeID.MultiplayerClient)
                              return;
                          for (int i = 0; i < 2; i++)
                              NPC.NewNPC(NPC.GetSource_Death(), (int)NPC.Center.X + (i == 0 ? -12 : 12), (int)NPC.Center.Y, NPCID.${base === "BlueSlime" ? "GreenSlime" : base});
                      }`
                    : ""
                }

                public override void ModifyNPCLoot(NPCLoot npcLoot) {
                    npcLoot.Add(ItemDropRule.Common(ItemID.${ENEMY_DROP[c.fx[0]]}, ${Math.max(2, Math.round(1 / n.chance))}));
                }
            }
        }`,
    ),
  };
}

function tmlBoss(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const life = n.health * 12;
  const summonsAdds = c.fx.includes("summon") || /minion|swarm|split|summon/.test(textOf(input));
  c.lang.push({ section: "NPCs", key: cls, display: input.modName });
  c.lang.push({ section: "Items", key: `${cls}Summon`, display: `${input.modName} Lure`, tooltip: `Summons ${clean(input.modName)}` });
  return {
    main: file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.Audio;
        using Terraria.GameContent.ItemDropRules;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.NPCs
        {
            ${header(c)}
            // A three-phase flying boss: stalk, dash, then a faster frenzy below 40% life. AI runs on the server
            // and every phase change sets netUpdate so all players see the same fight.
            public class ${cls} : ModNPC
            {
                public override string Texture => $"Terraria/Images/NPC_{NPCID.EyeofCthulhu}";
                ${tuningBlock(c)}

                private enum Phase { Stalk, Dash, Frenzy }
                private Phase CurrentPhase {
                    get => (Phase)NPC.ai[0];
                    set => NPC.ai[0] = (float)value;
                }
                private ref float Timer => ref NPC.ai[1];

                public override void SetStaticDefaults() {
                    Main.npcFrameCount[Type] = Main.npcFrameCount[NPCID.EyeofCthulhu];
                    NPCID.Sets.MPAllowedEnemies[Type] = true; // lets the summon item work in multiplayer
                    NPCID.Sets.BossBestiaryPriority.Add(Type);
                }

                public override void SetDefaults() {
                    NPC.width = 100;
                    NPC.height = 110;
                    NPC.lifeMax = ${life};
                    NPC.damage = ${Math.round(n.power * 4)};
                    NPC.defense = ${Math.round(n.power)};
                    NPC.knockBackResist = 0f;
                    NPC.noGravity = true;
                    NPC.noTileCollide = true;
                    NPC.boss = true;
                    NPC.npcSlots = 10f;
                    NPC.value = Item.buyPrice(gold: ${Math.max(2, Math.round(n.xp / 8))});
                    NPC.HitSound = SoundID.NPCHit1;
                    NPC.DeathSound = SoundID.NPCDeath1;
                    NPC.aiStyle = -1; // our own AI below
                    NPC.color = new Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                    if (!Main.dedServ)
                        Music = MusicID.Boss1;
                }

                public override void AI() {
                    if (NPC.target < 0 || NPC.target == 255 || Main.player[NPC.target].dead || !Main.player[NPC.target].active)
                        NPC.TargetClosest();
                    Player target = Main.player[NPC.target];
                    if (target.dead || !target.active) {
                        // Nobody left: fly away and despawn instead of camping the spawn point.
                        NPC.velocity.Y -= 0.4f;
                        NPC.EncourageDespawn(10);
                        return;
                    }

                    Timer++;
                    if (CurrentPhase != Phase.Frenzy && NPC.life < NPC.lifeMax * 0.4f) {
                        CurrentPhase = Phase.Frenzy;
                        Timer = 0;
                        SoundEngine.PlaySound(SoundID.Roar, NPC.Center);
                        ${
                          summonsAdds
                            ? code`
                              if (Main.netMode != NetmodeID.MultiplayerClient) {
                                  for (int i = 0; i < 3; i++)
                                      NPC.NewNPC(NPC.GetSource_FromAI(), (int)NPC.Center.X, (int)NPC.Center.Y, NPCID.ServantofCthulhu);
                              }`
                            : ""
                        }
                        NPC.netUpdate = true;
                    }

                    Vector2 toTarget = target.Center - NPC.Center;
                    switch (CurrentPhase) {
                        case Phase.Stalk:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 18)}, 0.05f);
                            if (Timer > ${Math.round(n.cooldown * 50) + 60}) {
                                CurrentPhase = Phase.Dash;
                                Timer = 0;
                                NPC.netUpdate = true;
                            }
                            break;
                        case Phase.Dash:
                            if (Timer == 1)
                                NPC.velocity = toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 42)};
                            NPC.velocity *= 0.975f;
                            if (Timer > 55) {
                                CurrentPhase = Phase.Stalk;
                                Timer = 0;
                                NPC.netUpdate = true;
                            }
                            break;
                        case Phase.Frenzy:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 28)}, 0.09f);
                            break;
                    }
                    NPC.rotation = NPC.velocity.ToRotation() - MathHelper.PiOver2;
                    Lighting.AddLight(NPC.Center, ${tint(c.fx[0])});
                }

                public override void FindFrame(int frameHeight) {
                    // The base sheet has a calm and an angry row of three frames each; frenzy uses the angry row.
                    NPC.frameCounter++;
                    int frame = (int)(NPC.frameCounter / 8 % 3) + (CurrentPhase == Phase.Frenzy ? 3 : 0);
                    NPC.frame.Y = frame * frameHeight;
                }

                public override void OnHitPlayer(Player target, Player.HurtInfo hurtInfo) {
                    ${c.fx.map((e) => `target.AddBuff(${TML_ON_HIT_PLAYER[e]}, Tuning.EffectTicks / 2);`)}
                }

                public override void ModifyNPCLoot(NPCLoot npcLoot) {
                    npcLoot.Add(ItemDropRule.Common(ItemID.${ENEMY_DROP[c.fx[0]]}, 1, ${n.radius}, ${n.radius + 8}));
                    npcLoot.Add(ItemDropRule.Common(ItemID.GreaterHealingPotion, 1, 5, 10));
                }

                public override void BossLoot(ref int potionType) {
                    potionType = ItemID.GreaterHealingPotion;
                }
            }

            /// <summary>Use at night to summon ${clean(input.modName)}.</summary>
            public class ${cls}Summon : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.SuspiciousLookingEye}";

                public override void SetStaticDefaults() {
                    ItemID.Sets.SortingPriorityBossSpawns[Type] = 12;
                }

                public override void SetDefaults() {
                    Item.width = 20;
                    Item.height = 20;
                    Item.maxStack = 20;
                    Item.rare = ItemRarityID.Orange;
                    Item.useAnimation = 30;
                    Item.useTime = 30;
                    Item.useStyle = ItemUseStyleID.HoldUp;
                    Item.consumable = true;
                }

                public override bool CanUseItem(Player player) => !Main.dayTime && !NPC.AnyNPCs(ModContent.NPCType<${cls}>());

                public override bool? UseItem(Player player) {
                    if (player.whoAmI == Main.myPlayer) {
                        SoundEngine.PlaySound(SoundID.Roar, player.position);
                        int type = ModContent.NPCType<${cls}>();
                        // Same pattern vanilla summons use: spawn directly in single player, ask the server otherwise.
                        if (Main.netMode != NetmodeID.MultiplayerClient)
                            NPC.SpawnOnPlayer(player.whoAmI, type);
                        else
                            NetMessage.SendData(MessageID.SpawnBossUseLicenseStartEvent, number: player.whoAmI, number2: type);
                    }
                    return true;
                }

                public override void AddRecipes() {
                    CreateRecipe()
                        .AddIngredient(ItemID.Lens, 6)
                        .AddIngredient(ItemID.${ENEMY_DROP[c.fx[0]] === "GoldCoin" ? "FallenStar" : ENEMY_DROP[c.fx[0]]}, 3)
                        .AddTile(TileID.DemonAltar)
                        .Register();
                }
            }
        }`,
    ),
  };
}

