function tmlMain(c: Tml): ModFile {
  const k = c.input.category.key;
  const t = textOf(c.input);
  if (k === "weapons" || k === "magic") return tmlWeapon(c).main;
  if (k === "items") return /\b(swords?|blades?|bows?|guns?|staffs?|wands?|yoyos?|weapon)\b/.test(t) ? tmlWeapon(c).main : tmlAccessory(c).main;
  if (k === "creatures") return /\b(boss|king|queen|lord|titan|monarch|phase|overlord|colossus)\b/.test(t) ? tmlBoss(c).main : tmlEnemy(c).main;
  if (k === "characters") return tmlCharacter(c).main;
  if (k === "vehicles") return tmlMount(c).main;
  if (k === "worlds") return tmlWorld(c).main;
  if (k === "quests") return tmlQuest(c).main;
  if (k === "interface") return tmlInterface(c).main;
  if (k === "audio") return tmlAudio(c).main;
  if (k === "shaders") return tmlShader(c).main;
  return tmlMechanic(c).main;
}

/** Minimal hjson writer for tModLoader 1.4.4 localization (file prefix = Mods.<mod>). */
function hjson(c: Tml): string {
  const bySection = new Map<string, Tml["lang"]>();
  for (const l of c.lang) bySection.set(l.section, [...(bySection.get(l.section) ?? []), l]);
  const q = (s: string) => (/^[\w .,'!?()-]*$/.test(s) && !/^\s|\s$/.test(s) && s ? s : JSON.stringify(s));
  const out: string[] = ["# Display names and tooltips (tModLoader 1.4.4 localization). tModLoader adds missing keys when you build."];
  for (const [section, rows] of bySection) {
    out.push(`${section}: {`);
    for (const r of rows) {
      out.push(`\t${r.key}: {`);
      out.push(`\t\tDisplayName: ${q(r.display)}`);
      if (r.tooltip !== undefined) out.push(r.tooltip.includes("\n") ? `\t\tTooltip:\n\t\t\t'''\n${r.tooltip.split("\n").map((x) => `\t\t\t${x}`).join("\n")}\n\t\t\t'''` : `\t\t${section === "Buffs" ? "Description" : "Tooltip"}: ${q(r.tooltip)}`);
      out.push("\t}");
    }
    out.push("}");
  }
  if (c.config) {
    out.push("Configs: {", `\t${c.cls}Config: {`, `\t\tDisplayName: ${q(`${c.input.modName} settings`)}`);
    for (const [k, label, tip] of CONFIG_FIELDS) out.push(`\t\t${k}: {`, `\t\t\tLabel: ${label}`, `\t\t\tTooltip: ${tip}`, "\t\t}");
    out.push("\t}", "}");
  }
  return out.join("\n") + "\n";
}

const CONFIG_FIELDS: [string, string, string][] = [
  ["Power", "Effect power", "Multiplies effect damage and healing"],
  ["EffectTicks", "Effect length (ticks)", "60 ticks is one second"],
  ["RadiusTiles", "Effect radius (tiles)", "How far area effects reach"],
  ["Chance", "Proc chance", "Chance for chance-based effects, 0 to 1"],
  ["CooldownSeconds", "Cooldown (seconds)", "Time between repeating effects"],
];

function tmlConfig(c: Tml): ModFile {
  const scope = c.side === "Client" ? "ClientSide" : "ServerSide";
  return file(
    `Common/${c.cls}Config.cs`,
