function manifest(o: {
  input: TemplateInput;
  flavor: TerrariaFlavor;
  internalName: string;
  version: string;
  side: string;
  playersInstall: boolean;
  entry: string;
  output: string;
  installPath: string;
  target: Record<string, string>;
  dependencies?: string[];
  permissions?: string[];
  commands?: string[];
}): ModFile {
  return file(
    "cyrus.mod.json",
    JSON.stringify(
      {
        schema: 1,
        game: "terraria",
        flavor: o.flavor,
        name: o.input.modName,
        internalName: o.internalName,
        version: o.version,
        target: o.target,
        side: o.side,
        playersInstall: o.playersInstall,
        entry: o.entry,
        output: o.output,
        installPath: o.installPath,
        dependencies: o.dependencies ?? [],
        ...(o.permissions ? { permissions: o.permissions } : {}),
        ...(o.commands ? { commands: o.commands } : {}),
        generator: { by: "Cyrus", model: MODEL_NAME[o.input.model], category: o.input.category.key },
      },
      null,
      2,
    ) + "\n",
  );
}

export function terrariaTModLoader(input: TemplateInput): Built {
  const { cls } = identity(input.modName);
  const n = numbers(input);
  const mod = /Mod$/.test(cls) ? cls : `${cls}Mod`;
  const c: Tml = {
    input,
    n,
    t: tuning(n),
    fx: effectsFor(input).map((e) => e.key),
    cls,
    mod,
    model: MODEL_NAME[input.model],
    config: input.model !== "katara",
    side: "Both",
    lang: [],
    extraDocs: [],
  };
  const main = tmlMain(c); // may switch c.side and fill c.lang / c.extraDocs
  const version = `${input.version}.0`;
  const build = file(
    "build.txt",
    code`
      displayName = ${clean(input.modName, 60)}
      author = Made with Cyrus
      version = ${version}
      side = ${c.side}
      hideCode = false
      hideResources = false
      includeSource = true
      buildIgnore = *.csproj, *.user, obj\\*, bin\\*, .vs\\*, cyrus.mod.json, README.md, CHANGELOG.md
      `,
  );
  const man = manifest({
    input,
    flavor: "tmodloader",
    internalName: mod,
    version,
    side: c.side === "Client" ? "client" : "both",
    playersInstall: true,
    entry: main.path,
    output: `${mod}.tmod`,
    installPath: "tModLoader/Mods (enable it in enabled.json)",
    target: { terraria: TML_TARGET.terraria, loader: "tModLoader", loaderVersion: TML_TARGET.month, release: TML_TARGET.release, dotnet: TML_TARGET.dotnet },
  });
  const modClass = file(
    `${mod}.cs`,
    code`
      using Terraria.ModLoader;

      namespace ${mod}
      {
          // The mod's entry point. The folder (and namespace) must be named ${mod} for tModLoader to build it.
          public class ${mod} : Mod
          {
          }
      }`,
  );
  const csproj = file(
    `${mod}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">
        <!-- tModLoader writes tModLoader.targets into your ModSources folder; this file is only needed for IDEs. -->
        <Import Project="..\\tModLoader.targets" />
        <PropertyGroup>
          <AssemblyName>${mod}</AssemblyName>
          <LangVersion>latest</LangVersion>
        </PropertyGroup>
      </Project>
      `,
  );
  const description = file(
    "description.txt",
    `${clean(input.modName, 60)}\n\n${deriveFeatures(input).map((f) => `- ${f}`).join("\n")}\n\n${c.side === "Client" ? "Client-side: only you need it." : "Everyone on the server needs it; the server sends it to players when they join."}\n\nMade with Cyrus.\n`,
  );
  const l10n = file(`Localization/en-US_Mods.${mod}.hjson`, hjson(c));
  const test = file(
    `Common/${cls}SelfCheck.cs`,
    code`
      using Terraria.ModLoader;

      namespace ${mod}.Common
      {
          // Load-time self check: tModLoader mods have no test runner, so this logs a warning in client.log /
          // server.log if a setting is out of the range the mod was balanced for. It never changes anything.
          public class ${cls}SelfCheck : ModSystem
          {
              public override void PostSetupContent() {
                  var cfg = ModContent.GetInstance<${cls}Config>();
                  if (cfg == null)
                      return;
                  if (cfg.Power > 2.5f)
                      Mod.Logger.Warn("Power is above 2.5: effects may out-scale endgame gear.");
                  if (cfg.EffectTicks > 1200)
                      Mod.Logger.Warn("Effects longer than 20 seconds can feel permanent in multiplayer.");
                  if (cfg.Chance > 0.6f)
                      Mod.Logger.Warn("Proc chance above 60% makes chance effects nearly constant.");
              }
          }
      }`,
  );
  // First three files must build and load on their own (Katara ships only those): content, build.txt, manifest.
  return { files: [main, build, man, modClass, csproj, description], config: c.config ? tmlConfig(c) : undefined, l10n, test, ...{ notes: c.extraDocs } } as Built;
}

/* ═════════════════════════ TShock plugin ═════════════════════════ */

type TsMode = "power" | "enchant" | "rewards" | "welcome" | "bossrush";
function tshockMode(input: TemplateInput): TsMode {
  const t = textOf(input);
  if (/boss ?rush|gauntlet|boss waves?|arena/.test(t)) return "bossrush";
  if (/welcome|greet|join|motd|first[- ]time|starter|kit|broadcast|announce|auto[- ]?message/.test(t)) return "welcome";
  if (/reward|bounty|loot|drop|coins?|gold|kill(s|ing)?\b|defeat|boss dies|economy/.test(t)) return "rewards";
  if (/swords?|blades?|weapons?|bows?|guns?|staffs?|enchant|imbue|holding|hits? with|on hit/.test(t) || input.category.key === "weapons" || input.category.key === "magic") return "enchant";
  return "power";
}

/** Server-side effect on `npc` struck by/near `ply` (TSPlayer). `dmg` = int base damage in scope. */
function tsEffect(e: EffectKey): string {
  const buff = (id: string) => `npc.AddBuff(BuffID.${id}, settings.EffectTicks);\nSyncBuffs(npc);`;
  switch (e) {
    case "frost":
      return buff("Frostburn2");
    case "fire":
      return buff("OnFire3");
    case "poison":
      return buff("Venom");
    case "void":
      return buff("ShadowFlame");
    case "lunar":
      return `if (!Main.dayTime) {\n    ${buff("Daybreak").replace("\n", "\n    ")}\n}`;
    case "storm":
      return code`
        // Chain lightning to up to three other enemies nearby.
        int arcs = 0;
        for (int i = 0; i < Main.maxNPCs && arcs < 3; i++) {
            NPC other = Main.npc[i];
            if (!other.active || other.whoAmI == npc.whoAmI || other.friendly || other.dontTakeDamage || other.townNPC)
                continue;
            if (Vector2.Distance(other.Center, npc.Center) > settings.RadiusTiles * 16f)
                continue;
            TSPlayer.Server.StrikeNPC(other.whoAmI, System.Math.Max(1, (int)(dmg * 0.5f * settings.Power)), 0f, 0);
            arcs++;
        }`;
    case "blink":
      return "if (Main.rand.NextDouble() < settings.Chance)\n    ply.Teleport(npc.position.X, npc.position.Y - 48f);";
    case "heal":
      return "ply.Heal(System.Math.Max(1, (int)(dmg * 0.05f * settings.Power)));";
    case "summon":
      return code`
        // Echoes: two extra spectral hits on the same enemy.
        if (Main.rand.NextDouble() < settings.Chance) {
            for (int i = 0; i < 2 && npc.active; i++)
                TSPlayer.Server.StrikeNPC(npc.whoAmI, System.Math.Max(1, (int)(dmg * 0.35f * settings.Power)), 0f, 0);
        }`;
    case "flight":
      return "ply.SetBuff(BuffID.Featherfall, settings.EffectTicks);";
    case "auto":
      return `ply.SetBuff(BuffID.Mining, settings.EffectTicks);\n${buff("Midas")}`;
    case "neon":
      return `ply.SetBuff(BuffID.Shine, settings.EffectTicks);\n${buff("Ichor")}`;
  }
}

interface Ts {
  input: TemplateInput;
  n: Nums;
  t: Tuning;
  fx: EffectKey[];
  cls: string;
  cmd: string;
  perm: string;
  mode: TsMode;
  name: string;
}

const BOSS_ORDER = ["KingSlime", "EyeofCthulhu", "EaterofWorldsHead", "QueenBee", "SkeletronHead", "Deerclops"];
const KIT: [RegExp, [string, number][]][] = [
  [/frost|ice|snow/, [["IceBlade", 1], ["HandWarmer", 1], ["LesserHealingPotion", 10]]],
  [/fire|flame|lava/, [["FieryGreatsword", 1], ["ObsidianSkinPotion", 3], ["LesserHealingPotion", 10]]],
];
const DEFAULT_KIT: [string, number][] = [["CopperShortsword", 1], ["Torch", 30], ["LesserHealingPotion", 10], ["Rope", 50]];

function tsSettings(s: Ts): { fields: string[]; json: Record<string, unknown> } {
  const base: [string, string, unknown][] = [
    ["float", "Power", s.t.power],
    ["int", "EffectTicks", s.t.effectTicks],
    ["int", "RadiusTiles", s.t.radiusTiles],
    ["double", "Chance", s.t.chance],
    ["int", "CooldownSeconds", s.t.cooldownSeconds],
  ];
  const extra: [string, string, unknown][] = [];
  const t = textOf(s.input);
  if (s.mode === "enchant") extra.push(["List<int>", "EnchantedItems", "ENCHANT"]);
  if (s.mode === "rewards") extra.push(["bool", "BossesOnly", !/any|every|all (enemies|kills)|each kill/.test(t)], ["int", "RewardItem", "ITEM:GoldCoin"], ["int", "RewardStack", 2 + (s.n.radius % 4)], ["bool", "Broadcast", true]);
  if (s.mode === "welcome") extra.push(["string", "WelcomeMessage", `Welcome to the server, {0}! Type /${s.cmd} for help.`], ["List<int[]>", "FirstJoinKit", "KIT"], ["int", "BroadcastMinutes", 10 + s.n.interval], ["List<string>", "Broadcasts", ["Be kind, build big.", "Bosses hit harder at night.", `Need help? Try /${s.cmd}.`]]);
  if (s.mode === "bossrush") extra.push(["List<int>", "Bosses", "BOSSES"], ["int", "SecondsBetween", 10], ["int", "RewardItem", "ITEM:GoldCoin"], ["int", "RewardStack", 5]);
  const kit = pick(KIT.map(([re, k]) => [re, JSON.stringify(k)] as [RegExp, string]), t, JSON.stringify(DEFAULT_KIT));
  const csInit = (type: string, v: unknown): string => {
    if (v === "ENCHANT") return `new List<int> { ItemID.${pick(MELEE_ART, t, "Muramasa")}, ItemID.${pick(BOW_ART, t, "PlatinumBow")}, ItemID.${pick(STAFF_SAFE, t, "AmethystStaff")} }`;
    if (v === "BOSSES") return `new List<int> { ${BOSS_ORDER.map((b) => `NPCID.${b}`).join(", ")} }`;
    if (v === "KIT") return `new List<int[]> { ${(JSON.parse(kit) as [string, number][]).map(([id, q]) => `new[] { ItemID.${id}, ${q} }`).join(", ")} }`;
    if (typeof v === "string" && v.startsWith("ITEM:")) return `ItemID.${v.slice(5)}`;
    if (type === "float") return f1(v as number);
    if (type === "double") return String(v);
    if (type === "List<string>") return `new List<string> { ${(v as string[]).map(csStr).join(", ")} }`;
    return typeof v === "string" ? csStr(v) : String(v);
  };
  const all = [...base, ...extra];
  return {
    fields: all.map(([type, name, v]) => `public ${type} ${name} { get; set; } = ${csInit(type, v)};`),
    json: Object.fromEntries(all.map(([, name, v]) => [name, typeof v === "string" && /^(ENCHANT|BOSSES|KIT|ITEM:)/.test(v) ? `(game ids, written by the plugin on first start)` : v])),
  };
}

function tsBody(s: Ts): { fields: string[]; init: string[]; dispose: string[]; methods: string; commands: string[] } {
  const fx = s.fx.map(tsEffect).join("\n");
  const effectMethod = code`
    /// <summary>Applies this mod's effect to one enemy on behalf of a player. Server-side; the game syncs the result.</summary>
    private void ApplyEffect(TSPlayer ply, NPC npc, int dmg)
    {
        if (applying)
            return; // our own strikes below fire the strike hook again; never recurse
        applying = true;
        try
        {
            ${fx}
        }
        finally
        {
            applying = false;
        }
    }`;
  const help = `/${s.cmd} - ${clean(deriveFeatures(s.input)[0] ?? s.input.modName, 80)}`;
  switch (s.mode) {
    case "power":
      return {
        fields: ["private readonly Dictionary<int, DateTime> lastUse = new Dictionary<int, DateTime>();"],
        init: [`Commands.ChatCommands.Add(new Command(UsePermission, OnCommand, ${csStr(s.cmd)}) { HelpText = ${csStr(help)}, AllowServer = false });`, "ServerApi.Hooks.ServerLeave.Register(this, OnLeave);"],
        dispose: ["Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnCommand);", "ServerApi.Hooks.ServerLeave.Deregister(this, OnLeave);"],
        commands: [s.cmd],
        methods: code`
          private void OnCommand(CommandArgs args)
          {
              TSPlayer ply = args.Player;
              if (!ply.RealPlayer || ply.Dead)
              {
                  ply.SendErrorMessage("You need to be alive in the world to use this.");
                  return;
              }
              if (lastUse.TryGetValue(ply.Index, out DateTime last) && (DateTime.UtcNow - last).TotalSeconds < settings.CooldownSeconds)
              {
                  ply.SendErrorMessage($"Recharging: {settings.CooldownSeconds - (int)(DateTime.UtcNow - last).TotalSeconds}s left.");
                  return;
              }
              lastUse[ply.Index] = DateTime.UtcNow;

              int hits = 0;
              int dmg = (int)(20 * settings.Power);
              for (int i = 0; i < Main.maxNPCs; i++)
              {
                  NPC npc = Main.npc[i];
                  if (!npc.active || npc.friendly || npc.townNPC || npc.dontTakeDamage || Vector2.Distance(npc.Center, ply.TPlayer.Center) > settings.RadiusTiles * 16f)
                      continue;
                  TSPlayer.Server.StrikeNPC(npc.whoAmI, dmg, 4f, npc.Center.X < ply.TPlayer.Center.X ? -1 : 1);
                  ApplyEffect(ply, npc, dmg);
                  hits++;
              }
              ply.SendSuccessMessage(hits == 0 ? "Nothing in range." : $"${clean(s.input.modName, 40)} hit {hits} {(hits == 1 ? "enemy" : "enemies")}.");
          }

          private void OnLeave(LeaveEventArgs args) => lastUse.Remove(args.Who);

          ${effectMethod}`,
      };
    case "enchant":
      return {
        fields: [],
        init: ["ServerApi.Hooks.NpcStrike.Register(this, OnStrike);"],
        dispose: ["ServerApi.Hooks.NpcStrike.Deregister(this, OnStrike);"],
        commands: [],
        methods: code`
          /// <summary>When a player with permission hits an enemy while holding one of the enchanted items, add the effect.</summary>
          private void OnStrike(NpcStrikeEventArgs args)
          {
              if (args.Handled || applying || args.Player == null || args.Npc == null || !args.Npc.active)
                  return;
              TSPlayer ply = TShock.Players[args.Player.whoAmI];
              if (ply == null || !ply.Active || !ply.HasPermission(UsePermission))
                  return;
              if (!settings.EnchantedItems.Contains(args.Player.HeldItem.type))
                  return;
              ApplyEffect(ply, args.Npc, args.Damage);
          }

          ${effectMethod}`,
      };
    case "rewards":
      return {
        fields: ["private readonly Dictionary<int, DateTime> recentBossKills = new Dictionary<int, DateTime>();"],
        init: ["ServerApi.Hooks.NpcKilled.Register(this, OnKilled);"],
        dispose: ["ServerApi.Hooks.NpcKilled.Deregister(this, OnKilled);"],
        commands: [],
        methods: code`
          private void OnKilled(NpcKilledEventArgs args)
          {
              NPC npc = args.npc;
              if (npc == null || npc.friendly || npc.townNPC || npc.SpawnedFromStatue)
                  return;
              if (settings.BossesOnly && !npc.boss)
                  return;
              if (npc.boss)
              {
                  // Multi-part bosses report a kill per segment: reward once per boss type per 30 seconds.
                  if (recentBossKills.TryGetValue(npc.type, out DateTime t) && (DateTime.UtcNow - t).TotalSeconds < 30)
                      return;
                  recentBossKills[npc.type] = DateTime.UtcNow;
                  foreach (TSPlayer p in TShock.Players)
                  {
                      if (p != null && p.Active && p.RealPlayer && p.HasPermission(UsePermission))
                          p.GiveItem(settings.RewardItem, settings.RewardStack);
                  }
                  if (settings.Broadcast)
                      TShock.Utils.Broadcast($"{npc.FullName} was defeated! Everyone online gets a reward.", ${TINT[s.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                  return;
              }
              // Regular enemy: reward the last player who hit it.
              int who = npc.lastInteraction;
              if (who < 0 || who >= Main.maxPlayers)
                  return;
              TSPlayer killer = TShock.Players[who];
              if (killer != null && killer.Active && killer.HasPermission(UsePermission) && Main.rand.NextDouble() < settings.Chance)
                  killer.GiveItem(settings.RewardItem, 1);
          }`,
      };
    case "welcome":
      return {
        fields: ["private HashSet<string> seen = new HashSet<string>();", "private int ticks;", "private int nextBroadcast;"],
        init: [
          "LoadSeen();",
          "ServerApi.Hooks.NetGreetPlayer.Register(this, OnGreet);",
          "ServerApi.Hooks.GameUpdate.Register(this, OnUpdate);",
          `Commands.ChatCommands.Add(new Command(UsePermission, OnHelp, ${csStr(s.cmd)}) { HelpText = ${csStr(`/${s.cmd} - server tips`)} });`,
        ],
        dispose: ["ServerApi.Hooks.NetGreetPlayer.Deregister(this, OnGreet);", "ServerApi.Hooks.GameUpdate.Deregister(this, OnUpdate);", "Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnHelp);"],
        commands: [s.cmd],
        methods: code`
          private static string SeenPath => Path.Combine(TShock.SavePath, ${csStr(`${s.cls}.seen.json`)});

          private void LoadSeen()
          {
              try
              {
                  if (File.Exists(SeenPath))
                      seen = JsonConvert.DeserializeObject<HashSet<string>>(File.ReadAllText(SeenPath)) ?? new HashSet<string>();
              }
              catch (Exception ex)
              {
                  TShock.Log.ConsoleError($"[${s.name}] Could not read {SeenPath}: {ex.Message}");
              }
          }

          private void OnGreet(GreetPlayerEventArgs args)
          {
              TSPlayer ply = TShock.Players[args.Who];
              if (ply == null || !ply.RealPlayer)
                  return;
              ply.SendInfoMessage(string.Format(settings.WelcomeMessage, ply.Name));
              // First visit only: keyed by character name, remembered in this plugin's own file.
              if (!seen.Add(ply.Name))
                  return;
              foreach (int[] entry in settings.FirstJoinKit)
              {
                  if (entry.Length == 2 && entry[0] > 0 && entry[1] > 0)
                      ply.GiveItem(entry[0], entry[1]);
              }
              ply.SendSuccessMessage("A starter kit has been dropped at your feet.");
              try
              {
                  File.WriteAllText(SeenPath, JsonConvert.SerializeObject(seen));
              }
              catch (Exception ex)
              {
                  TShock.Log.ConsoleError($"[${s.name}] Could not save {SeenPath}: {ex.Message}");
              }
          }

          private void OnUpdate(EventArgs args)
          {
              // GameUpdate runs 60 times a second: count updates instead of starting a timer thread.
              if (settings.Broadcasts.Count == 0 || settings.BroadcastMinutes <= 0 || ++ticks < settings.BroadcastMinutes * 3600)
                  return;
              ticks = 0;
              TShock.Utils.Broadcast(settings.Broadcasts[nextBroadcast++ % settings.Broadcasts.Count], ${TINT[s.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
          }

          private void OnHelp(CommandArgs args)
          {
              foreach (string line in settings.Broadcasts)
                  args.Player.SendInfoMessage(line);
          }`,
      };
    case "bossrush":
      return {
        fields: ["private int stage = -1;", "private int waitTicks;", "private TSPlayer host;"],
        init: [
          `Commands.ChatCommands.Add(new Command(AdminPermission, OnCommand, ${csStr(s.cmd)}) { HelpText = ${csStr(`/${s.cmd} start|stop|status - fight the bosses one after another`)}, AllowServer = false });`,
          "ServerApi.Hooks.NpcKilled.Register(this, OnKilled);",
          "ServerApi.Hooks.GameUpdate.Register(this, OnUpdate);",
        ],
        dispose: ["Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnCommand);", "ServerApi.Hooks.NpcKilled.Deregister(this, OnKilled);", "ServerApi.Hooks.GameUpdate.Deregister(this, OnUpdate);"],
        commands: [s.cmd],
        methods: code`
          private bool Running => stage >= 0;

          private void OnCommand(CommandArgs args)
          {
              string sub = args.Parameters.Count > 0 ? args.Parameters[0].ToLowerInvariant() : "status";
              switch (sub)
              {
                  case "start":
                      if (Running)
                      {
                          args.Player.SendErrorMessage("A boss rush is already running.");
                          return;
                      }
                      if (settings.Bosses.Count == 0)
                      {
                          args.Player.SendErrorMessage("No bosses configured.");
                          return;
                      }
                      host = args.Player;
                      stage = 0;
                      waitTicks = 60 * 3;
                      TShock.Utils.Broadcast($"Boss rush started by {host.Name}: {settings.Bosses.Count} bosses incoming!", 255, 120, 80);
                      break;
                  case "stop":
                      stage = -1;
                      TShock.Utils.Broadcast("Boss rush stopped.", 200, 200, 200);
                      break;
                  default:
                      args.Player.SendInfoMessage(Running ? $"Boss {stage + 1} of {settings.Bosses.Count}." : $"No boss rush running. /${s.cmd} start");
                      break;
              }
          }

          private void OnUpdate(EventArgs args)
          {
              if (!Running || waitTicks <= 0 || --waitTicks > 0)
                  return;
              if (host == null || !host.Active || host.Dead)
              {
                  stage = -1;
                  TShock.Utils.Broadcast("Boss rush ended: the host left or died.", 200, 200, 200);
                  return;
              }
              int type = settings.Bosses[stage];
              TSPlayer.Server.SpawnNPC(type, Lang.GetNPCNameValue(type), 1, host.TileX, host.TileY - 20, 30, 10);
          }

          private void OnKilled(NpcKilledEventArgs args)
          {
              if (!Running || args.npc == null || !args.npc.boss || stage >= settings.Bosses.Count || args.npc.type != settings.Bosses[stage])
                  return;
              stage++;
              if (stage >= settings.Bosses.Count)
              {
                  stage = -1;
                  TShock.Utils.Broadcast("Boss rush complete! Rewards for everyone online.", 120, 255, 140);
                  foreach (TSPlayer p in TShock.Players)
                  {
                      if (p != null && p.Active && p.RealPlayer)
                          p.GiveItem(settings.RewardItem, settings.RewardStack);
                  }
                  return;
              }
              waitTicks = settings.SecondsBetween * 60;
              TShock.Utils.Broadcast($"Next boss in {settings.SecondsBetween} seconds ({stage + 1}/{settings.Bosses.Count}).", 255, 200, 80);
          }`,
      };
  }
}

export function terrariaTShock(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const mode = tshockMode(input);
  const cmd = (snake.replace(/_/g, "").slice(0, 16) || "cyrus").toLowerCase();
  const s: Ts = { input, n, t: tuning(n), fx: effectsFor(input).map((e) => e.key), cls, cmd, perm: `cyrus.${cmd}`, mode, name: clean(input.modName, 60) };
  const body = tsBody(s);
  const settings = tsSettings(s);
  const usesStrike = /TSPlayer\.Server\.StrikeNPC|SyncBuffs/.test(body.methods);
  const version = `${input.version}.0.0`;
  const permissions = mode === "bossrush" ? [`${s.perm}.admin`] : [`${s.perm}.use`];
  const plugin = file(
    `${cls}.cs`,
    code`
      // ${s.name}: a TShock server plugin made with Cyrus (${MODEL_NAME[input.model]}), v${input.version}.
      // Target: TShock ${TSHOCK_TARGET.tshock} (Terraria ${TSHOCK_TARGET.terraria}), TerrariaServerAPI ${TSHOCK_TARGET.tsapi}, .NET 9.
      // Runs on the server only: players join with the normal game and install nothing.
      using System;
      using System.Collections.Generic;
      using System.IO;
      using Microsoft.Xna.Framework;
      using Newtonsoft.Json;
      using Terraria;
      using Terraria.ID;
      using TerrariaApi.Server;
      using TShockAPI;
      using TShockAPI.Hooks;

      namespace Cyrus.${cls}
      {
          [ApiVersion(2, 1)]
          public class ${cls}Plugin : TerrariaPlugin
          {
              public override string Name => ${csStr(s.name)};
              public override Version Version => new Version(${version.split(".").join(", ")});
              public override string Author => "Made with Cyrus";
              public override string Description => ${csStr(clean(deriveFeatures(input).join(". "), 200))};

              public const string UsePermission = ${csStr(`${s.perm}.use`)};
              public const string AdminPermission = ${csStr(`${s.perm}.admin`)};

              /// <summary>This plugin's settings file, inside TShock's own folder (never a hard-coded path).</summary>
              private static string ConfigPath => Path.Combine(TShock.SavePath, ${csStr(`${cls}.json`)});

              private Settings settings = new Settings();
              ${usesStrike || mode === "enchant" || mode === "power" ? "[ThreadStatic] private static bool applying;" : ""}
              ${body.fields}

              public ${cls}Plugin(Main game) : base(game)
              {
              }

              public override void Initialize()
              {
                  LoadSettings();
                  GeneralHooks.ReloadEvent += OnReload;
                  ${body.init}
              }

              protected override void Dispose(bool disposing)
              {
                  if (disposing)
                  {
                      GeneralHooks.ReloadEvent -= OnReload;
                      ${body.dispose}
                  }
                  base.Dispose(disposing);
              }

              ${body.methods}

              ${
                usesStrike
                  ? code`
                    /// <summary>Tell every player about the enemy's new debuffs.</summary>
                    private static void SyncBuffs(NPC npc) => NetMessage.SendData((int)PacketTypes.NpcUpdateBuff, -1, -1, null, npc.whoAmI);`
                  : ""
              }

              private void OnReload(ReloadEventArgs args)
              {
                  LoadSettings();
                  args.Player?.SendSuccessMessage(${csStr(`[${s.name}] settings reloaded.`)});
              }

              /// <summary>Reads the settings file, writing the defaults the first time. A broken file never stops the server.</summary>
              private void LoadSettings()
              {
                  try
                  {
                      if (File.Exists(ConfigPath))
                          settings = JsonConvert.DeserializeObject<Settings>(File.ReadAllText(ConfigPath)) ?? new Settings();
                      else
                          File.WriteAllText(ConfigPath, JsonConvert.SerializeObject(settings, Formatting.Indented));
                      settings.Clamp();
                  }
                  catch (Exception ex)
                  {
                      settings = new Settings();
                      TShock.Log.ConsoleError($"[${s.name}] Could not read {ConfigPath}, using defaults: {ex.Message}");
                  }
              }

              public class Settings
              {
                  ${settings.fields}

                  /// <summary>Keeps hand-edited values inside safe limits.</summary>
                  public void Clamp()
                  {
                      Power = Math.Clamp(Power, 0.1f, 5f);
                      EffectTicks = Math.Clamp(EffectTicks, 30, 3600);
                      RadiusTiles = Math.Clamp(RadiusTiles, 1, 60);
                      Chance = Math.Clamp(Chance, 0d, 1d);
                      CooldownSeconds = Math.Clamp(CooldownSeconds, 0, 3600);
                  }
              }
          }
      }`,
  );
  const csproj = file(
    `${cls}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">
        <!-- Build: dotnet build -c Release  (needs the .NET 9 SDK). Output: bin/Release/${TSHOCK_TARGET.dotnet}/${cls}.dll -->
        <PropertyGroup>
          <TargetFramework>${TSHOCK_TARGET.dotnet}</TargetFramework>
          <AssemblyName>${cls}</AssemblyName>
          <RootNamespace>Cyrus.${cls}</RootNamespace>
          <Version>${version}</Version>
          <Nullable>disable</Nullable>
          <ImplicitUsings>disable</ImplicitUsings>
          <LangVersion>latest</LangVersion>
          <EnableDynamicLoading>true</EnableDynamicLoading>
        </PropertyGroup>
        <ItemGroup>
          <!-- TShock's own NuGet package (GPL-3.0). The server already has these files, so they are not copied out. -->
          <PackageReference Include="${TSHOCK_TARGET.nuget.id}" Version="${TSHOCK_TARGET.nuget.version}" ExcludeAssets="runtime" PrivateAssets="all" />
        </ItemGroup>
      </Project>
      `,
  );
  const man = manifest({
    input,
    flavor: "tshock",
    internalName: cls,
    version,
    side: "server",
    playersInstall: false,
    entry: plugin.path,
    output: `${cls}.dll`,
    installPath: "/opt/terraria-plugins",
    target: { terraria: TSHOCK_TARGET.terraria, loader: "TShock", loaderVersion: TSHOCK_TARGET.tshock, api: `TerrariaServerAPI ${TSHOCK_TARGET.tsapi}`, dotnet: TSHOCK_TARGET.dotnet },
    permissions,
    commands: body.commands.map((x) => `/${x}`),
  });
  const config = file(`${cls}.json`, JSON.stringify(settings.json, null, 2) + "\n");
  const test = file(
    `${cls}.SelfCheck.cs`,
    code`
      using TShockAPI;

      namespace Cyrus.${cls}
      {
          // Load-time self check (TShock plugins have no test runner): warns in the server log when a setting is
          // outside the range this plugin was balanced for. Call it from Initialize() after LoadSettings().
          internal static class SelfCheck
          {
              internal static void Run(${cls}Plugin.Settings s)
              {
                  if (s.Power > 3f)
                      TShock.Log.ConsoleWarn("[${s.name}] Power above 3 out-scales most vanilla gear.");
                  if (s.EffectTicks > 1200)
                      TShock.Log.ConsoleWarn("[${s.name}] Effects longer than 20 seconds feel permanent.");
                  if (s.RadiusTiles > 40)
                      TShock.Log.ConsoleWarn("[${s.name}] A radius over 40 tiles reaches off screen.");
              }
          }
      }`,
  );
  return { files: [plugin, csproj, man], config, test } as Built;
}

/* ═════════════════════════ entry points used by templates.ts ═════════════════════════ */

export function terrariaMod(input: TemplateInput): Built {
  return terrariaFlavor(input).flavor === "tshock" ? terrariaTShock(input) : terrariaTModLoader(input);
}

export function terrariaInstallSteps(input: TemplateInput): string[] {
  const { cls } = identity(input.modName);
  if (terrariaFlavor(input).flavor === "tshock") {
    return [
      `Build it: \`dotnet build -c Release\` (needs the free .NET 9 SDK). The plugin is \`bin/Release/${TSHOCK_TARGET.dotnet}/${cls}.dll\`.`,
      "On your Nxeon Terraria server, upload the .dll to `/opt/terraria-plugins` in Files, then restart the server.",
      `Check the console for \`${clean(input.modName, 60)} v${input.version}.0.0 initiated.\` and grant the permission (for example \`/group addperm default cyrus.${(identity(input.modName).snake.replace(/_/g, "").slice(0, 16) || "cyrus").toLowerCase()}.use\`). Players install nothing.`,
    ];
  }
  const mod = /Mod$/.test(cls) ? cls : `${cls}Mod`;
  return [
    "Install tModLoader (free on Steam for anyone who owns Terraria) and open Workshop → Develop Mods → Open Sources.",
    `Put this folder there named exactly \`${mod}\`, then click **Build + Reload** and enable it.`,
    "Multiplayer needs a tModLoader server (Nxeon Terraria servers run TShock today). Players who join get the mod sent to them automatically; tModLoader warns that it is not from the Workshop, and they accept it.",
  ];
}

/** Extra plain-language notes for the Explain/notes tab. */
export function terrariaNotes(input: TemplateInput): string[] {
  const f = terrariaFlavor(input);
  const out = [f.reason];
  if (f.flavor === "tshock") {
    out.push(`Built for TShock ${TSHOCK_TARGET.tshock} on Terraria ${TSHOCK_TARGET.terraria}, the version Nxeon Terraria servers run. Players must be on the same Terraria version to join.`);
    out.push("Server plugins can only use what the base game has: vanilla items, enemies, bosses and buffs. For brand-new items or bosses, ask for a tModLoader content mod.");
  } else {
    out.push(`Built for tModLoader ${TML_TARGET.month} stable (Terraria ${TML_TARGET.terraria}). tModLoader has not moved to 1.4.5 yet, so this mod cannot run on a 1.4.5 TShock server.`);
    out.push("Placeholder art is borrowed from the player's own game until you add your own PNGs; nothing is copied into the mod.");
  }
  const built = terrariaMod(input) as Built & { notes?: string[] };
  return [...out, ...(built.notes ?? [])];
}

/** Stable seed for callers that want to show which mode/kind was chosen (tests, Explain tab). */
export function terrariaPlan(input: TemplateInput): { flavor: TerrariaFlavor; kind: string } {
  const f = terrariaFlavor(input).flavor;
  if (f === "tshock") return { flavor: f, kind: `plugin:${tshockMode(input)}` };
  const k = input.category.key;
  const arch = ARCH[k];
  return { flavor: f, kind: `${arch}:${k === "weapons" || k === "magic" ? weaponKind(input) : k}:${hashStr(input.modName) % 1}` };
}

