/**
 * Terraria · C#. Two real targets, picked per request by `terrariaFlavor`:
 *
 *  - TShock server plugin (TerrariaServerAPI 2.1, .NET 9, TShock = the release Nxeon servers are pinned to).
 *    Server-only, vanilla content only: commands, permissions, hooks on hits/kills/joins, vanilla buffs/items/bosses.
 *  - tModLoader content mod (tModLoader 1.4.4 stable, .NET 8): new items, enemies, bosses, mounts, world gen, UI,
 *    music, screen effects. Every player runs it too (side=Both is sent from the server on join).
 *
 * Every API used here was checked against the loaders' own source (tModLoader stable + ExampleMod, TShock v6.2.1,
 * TerrariaServerAPI at the commit TShock pins) and the output is compiled on the build host by
 * scripts/cyrus/terraria-compile-check.sh (see docs/DOCUMENTATION.md, "Cyrus · Terraria"). Rules that keep players'
 * games safe:
 *  - no art is shipped: content points at the matching image of the player's own game ("Terraria/Images/Item_N")
 *    until the creator uploads their own, so every mod loads;
 *  - spawning, enemy health and boss summons only run where the game expects (server / single player); effects on
 *    the player only run for the local player; enemy AI changes set netUpdate;
 *  - no threads, sleeps, file access outside the mod's own config, network, processes or save editing;
 *  - plugins catch config errors instead of crashing TShock, deregister every hook on Dispose and guard re-entrant
 *    strike hooks.
 */
import type { CategoryKey, ModFile } from "@/lib/cyrus/types";
import { TML_TARGET, TSHOCK_TARGET, type TerrariaFlavor } from "@/lib/cyrus/games/terraria";
import { ARCH, code, deriveFeatures, effectsFor, file, hashStr, identity, MODEL_NAME, numbers, type Built, type EffectKey, type TemplateInput } from "../kit";

type Nums = ReturnType<typeof numbers>;
const pick = (table: [RegExp, string][], text: string, fallback: string) => table.find(([re]) => re.test(text))?.[1] ?? fallback;
const csStr = (s: string) => JSON.stringify(s); // a JSON string literal is a valid C# regular string literal for our inputs
const f1 = (x: number) => `${Number(x.toFixed(2))}f`;
const textOf = (input: TemplateInput) => `${input.prompt} ${input.modName}`.toLowerCase();
const clean = (s: string, max = 160) => s.replace(/[\u0000-\u001f"\\{}]/g, " ").replace(/\s+/g, " ").trim().slice(0, max);

/* ═════════════════════════ flavour: TShock plugin or tModLoader mod? ═════════════════════════ */

const STRONG_TSHOCK = /\b(tshock|server[- ]side|server[- ]only|server plugins?|vanilla (clients?|players?)|no (client|mod) installs?|nothing to install|without (installing|mods)|boss ?rush)\b/;
const STRONG_TML = /\b(tmodloader|tmod|tml|content mod)\b/;
const TSHOCK_WORDS = /\b(plugin|commands?|permissions?|admins?|moderat\w*|broadcasts?|announce\w*|welcome|greet\w*|motd|joins?|kick|ban|mute|ranks?|economy|currency|bank|shop|warps?|homes?|regions?|protect\w*|grief\w*|kits?|starter|waves?|leaderboard|stats|vote|afk|chat|rewards?|bounty|server)\b|(^|\s)\/[a-z]{2,}/;
const TML_WORDS = /\b(new (items?|weapons?|enem(y|ies)|boss(es)?|npcs?|biomes?|blocks?|tiles?|ores?|mounts?|accessor(y|ies)|projectiles?)|swords?|blades?|greatsword|bows?|guns?|rifle|staffs?|wands?|tome|yoyos?|spears?|enem(y|ies)|mobs?|creatures?|npcs?|biomes?|ores?|structures?|accessor(y|ies)|boots|wings|amulet|charm|ring|mounts?|ride|shaders?|screen|music|soundtrack|textures?|sprites?|hud|ui|overlay|moth|slime|minion)\b/;
const TSHOCK_CATS: CategoryKey[] = ["mechanics", "quests"];

/** Which of Terraria's two modding worlds this request belongs in, and why (shown in the notes). */
export function terrariaFlavor(input: TemplateInput): { flavor: TerrariaFlavor; reason: string } {
  const t = textOf(input);
  let ts = 0;
  let tm = 0;
  if (STRONG_TSHOCK.test(t)) ts += 6;
  if (STRONG_TML.test(t)) tm += 6;
  ts += (t.match(new RegExp(TSHOCK_WORDS.source, "g")) ?? []).length;
  tm += (t.match(new RegExp(TML_WORDS.source, "g")) ?? []).length;
  if (TSHOCK_CATS.includes(input.category.key)) ts += 1.5;
  else tm += 1.5;
  const flavor: TerrariaFlavor = ts > tm ? "tshock" : "tmodloader";
  return {
    flavor,
    reason:
      flavor === "tshock"
        ? "This works with what the game already has, so it is built as a server plugin: it runs only on the server and players install nothing."
        : "This adds new content (new items, enemies or visuals) that the normal game cannot show, so it is built as a tModLoader content mod that every player also runs.",
  };
}

/* ═════════════════════════ shared tuning (numbers every mode reads) ═════════════════════════ */

interface Tuning {
  power: number; // multiplier on effect damage/heal
  effectTicks: number; // debuff length, 60 ticks = 1 second
  radiusTiles: number;
  chance: number; // 0..1 for proc effects
  cooldownSeconds: number;
}
const tuning = (n: Nums): Tuning => ({
  power: Number((n.intensity).toFixed(2)),
  effectTicks: n.duration * 60,
  radiusTiles: n.radius + 6,
  chance: n.chance,
  cooldownSeconds: Math.max(2, Math.round(n.cooldown * 2)),
});

/* ═════════════════════════ tModLoader effects, per call site ═════════════════════════ */

/** Inside OnHitNPC(...): `player` (attacker), `target` (NPC), `hit`, `damageDone`. */
function tmlOnHitNpc(e: EffectKey): string {
  switch (e) {
    case "frost":
      return "target.AddBuff(BuffID.Frostburn2, Tuning.EffectTicks);";
    case "fire":
      return "target.AddBuff(BuffID.OnFire3, Tuning.EffectTicks);";
    case "poison":
      return "target.AddBuff(BuffID.Venom, Tuning.EffectTicks);";
    case "void":
      return "target.AddBuff(BuffID.ShadowFlame, Tuning.EffectTicks);";
    case "lunar":
      return "if (!Main.dayTime)\n    target.AddBuff(BuffID.Daybreak, Tuning.EffectTicks);";
    case "storm":
      return code`
        // Chain lightning: arc to up to three other enemies nearby. SimpleStrikeNPC syncs the hit in multiplayer.
        int arcs = 0;
        for (int i = 0; i < Main.maxNPCs && arcs < 3; i++) {
            NPC other = Main.npc[i];
            if (!other.active || other.whoAmI == target.whoAmI || !other.CanBeChasedBy() || other.Distance(target.Center) > Tuning.RadiusTiles * 16f)
                continue;
            other.SimpleStrikeNPC(System.Math.Max(1, (int)(damageDone * 0.5f * Tuning.Power)), hit.HitDirection);
            for (int d = 0; d < 6; d++)
                Dust.NewDust(other.position, other.width, other.height, DustID.Electric);
            arcs++;
        }`;
    case "blink":
      return code`
        // Blink behind the target (local player only, then tell everyone else where we went).
        if (player.whoAmI == Main.myPlayer && Main.rand.NextFloat() < Tuning.Chance) {
            Vector2 spot = target.Center + new Vector2(-target.direction * (target.width / 2f + 24f), 0f) - player.Size / 2f;
            if (!Collision.SolidCollision(spot, player.width, player.height)) {
                player.Teleport(spot, TeleportationStyleID.RodOfDiscord);
                NetMessage.SendData(MessageID.TeleportEntity, -1, -1, null, 0, player.whoAmI, spot.X, spot.Y, TeleportationStyleID.RodOfDiscord);
            }
        }`;
    case "heal":
      return "if (player.whoAmI == Main.myPlayer && !target.immortal)\n    player.Heal(System.Math.Max(1, (int)(damageDone * 0.05f * Tuning.Power)));";
    case "summon":
      return code`
        // Echoes: two friendly homing eaters join the fight (spawned by the owner, which the game syncs).
        if (player.whoAmI == Main.myPlayer && Main.rand.NextFloat() < Tuning.Chance) {
            for (int i = 0; i < 2; i++)
                Projectile.NewProjectile(player.GetSource_OnHit(target), target.Center, Main.rand.NextVector2CircularEdge(6f, 6f), ProjectileID.TinyEater, System.Math.Max(1, damageDone / 3), 0f, player.whoAmI);
        }`;
    case "flight":
      return "if (player.whoAmI == Main.myPlayer) {\n    player.wingTime = player.wingTimeMax;\n    player.AddBuff(BuffID.Featherfall, Tuning.EffectTicks);\n}";
    case "auto":
      return "if (player.whoAmI == Main.myPlayer)\n    player.AddBuff(BuffID.Mining, Tuning.EffectTicks);\ntarget.AddBuff(BuffID.Midas, Tuning.EffectTicks);";
    case "neon":
      return "if (player.whoAmI == Main.myPlayer)\n    player.AddBuff(BuffID.Shine, Tuning.EffectTicks);\ntarget.AddBuff(BuffID.Ichor, Tuning.EffectTicks);";
  }
}

