function tuningBlock(c: Tml): string {
  if (c.config) return `private static ${c.cls}Config Tuning => ModContent.GetInstance<${c.cls}Config>();`;
  return code`
    private static class Tuning
    {
        public const float Power = ${f1(c.t.power)};
        public const int EffectTicks = ${c.t.effectTicks};
        public const int RadiusTiles = ${c.t.radiusTiles};
        public const float Chance = ${f1(c.t.chance)};
        public const int CooldownSeconds = ${c.t.cooldownSeconds};
    }`;
}

const header = (c: Tml) =>
  code`
