    // Target: tModLoader ${TML_TARGET.month} stable (Terraria ${TML_TARGET.terraria}). Placeholder art comes from the player's own game;
    // drop a PNG with the class name next to this file and delete the Texture line to use your own.`;

const hitFx = (c: Tml) => c.fx.map(tmlOnHitNpc);
const dustLine = (c: Tml, where: string) => `Dust.NewDust(${where}.position, ${where}.width, ${where}.height, ${DUST[c.fx[0]]});`;

