type WeaponKind = "sword" | "yoyo" | "bow" | "gun" | "magic";
function weaponKind(input: TemplateInput): WeaponKind {
  const t = textOf(input);
  if (/\byoyos?\b/.test(t)) return "yoyo";
  if (/\b(bows?|longbow|crossbow|arrows?)\b/.test(t)) return "bow";
  if (/\b(guns?|rifle|pistol|blaster|shotgun|launcher|cannon|minigun)\b/.test(t)) return "gun";
  if (input.category.key === "magic" || /\b(staffs?|wands?|tome|spell|scepter|rod)\b/.test(t)) return "magic";
  return "sword";
}

function tmlWeapon(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const kind = weaponKind(input);
  const t = textOf(input);
  const dmg = Math.round(n.power * (kind === "magic" ? 4.5 : 6));
  const use = Math.max(10, Math.round(n.cooldown * 5));
  const rare = n.power > 10 ? "ItemRarityID.Lime" : "ItemRarityID.Pink";
  const hard = /hardmode|hard mode|endgame|late game|post[- ]?moon/.test(t) || n.power > 9;
  const recipe = hard
    ? code`
        CreateRecipe()
            .AddIngredient(ItemID.HallowedBar, ${n.radius + 6})
            .AddIngredient(ItemID.SoulofMight, ${n.interval + 2})
            .AddTile(TileID.MythrilAnvil)
            .Register();`
    : code`
        CreateRecipe()
            .AddIngredient(ItemID.${c.fx[0] === "frost" ? "IceBlock" : c.fx[0] === "fire" ? "HellstoneBar" : "FallenStar"}, ${n.radius + 4})
            .AddRecipeGroup(RecipeGroupID.IronBar, ${n.interval + 3})
            .AddTile(TileID.Anvils)
            .Register();`;
  c.lang.push({ section: "Items", key: cls, display: input.modName, tooltip: clean(deriveFeatures(input).slice(0, 2).join("\n")) });

  if (kind === "sword") {
    const art = pick(MELEE_ART, t, "Muramasa");
    return {
      main: file(
        `Content/Items/${cls}.cs`,
        code`
          using Microsoft.Xna.Framework;
          using Terraria;
          using Terraria.ID;
          using Terraria.ModLoader;

          namespace ${mod}.Content.Items
          {
              ${header(c)}
              public class ${cls} : ModItem
              {
                  public override string Texture => $"Terraria/Images/Item_{ItemID.${art}}";
                  ${tuningBlock(c)}

                  public override void SetDefaults() {
                      Item.width = 40;
                      Item.height = 40;
                      Item.useStyle = ItemUseStyleID.Swing;
                      Item.useTime = ${use};
                      Item.useAnimation = ${use};
                      Item.autoReuse = true;
                      Item.DamageType = DamageClass.Melee;
                      Item.damage = ${dmg};
                      Item.knockBack = ${f1(n.power / 2)};
                      Item.crit = 6;
                      Item.value = Item.sellPrice(gold: ${Math.max(1, Math.round(n.power))});
                      Item.rare = ${rare};
                      Item.UseSound = SoundID.Item1;
                  }

                  public override void MeleeEffects(Player player, Rectangle hitbox) {
                      if (Main.rand.NextBool(3))
                          Dust.NewDust(new Vector2(hitbox.X, hitbox.Y), hitbox.Width, hitbox.Height, ${DUST[c.fx[0]]});
                  }

                  public override void OnHitNPC(Player player, NPC target, NPC.HitInfo hit, int damageDone) {
                      ${hitFx(c)}
                  }

                  public override void AddRecipes() {
                      ${recipe}
                  }
              }
          }`,
      ),
    };
  }

  // Everything else fires our own projectile, so on-hit effects belong to the projectile.
  const projBase =
    kind === "yoyo" ? pick(YOYO_ART, t, "Code1") : kind === "bow" ? "WoodenArrowFriendly" : kind === "gun" ? "Bullet" : BOLT[c.fx[0]];
  const itemArt =
    kind === "yoyo" ? pick(YOYO_ART, t, "Code1") : kind === "bow" ? pick(BOW_ART, t, "PlatinumBow") : kind === "gun" ? pick(GUN_ART, t, "Handgun") : pick(STAFF_SAFE, t, "AmethystStaff");
  const itemDefaults: Record<Exclude<WeaponKind, "sword">, string> = {
    yoyo: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = 25;
      Item.useAnimation = 25;
      Item.noMelee = true;
      Item.noUseGraphic = true;
      Item.channel = true;
      Item.DamageType = DamageClass.MeleeNoSpeed;
      Item.UseSound = SoundID.Item1;
      Item.shoot = ModContent.ProjectileType<${cls}Projectile>();
      Item.shootSpeed = 16f;`,
    bow: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${use};
      Item.useAnimation = ${use};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Ranged;
      Item.useAmmo = AmmoID.Arrow;
      Item.UseSound = SoundID.Item5;
      Item.shoot = ProjectileID.PurificationPowder; // replaced by the ammo, then by our arrow in ModifyShootStats
      Item.shootSpeed = 11f;`,
    gun: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${Math.max(6, Math.round(use / 2))};
      Item.useAnimation = ${Math.max(6, Math.round(use / 2))};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Ranged;
      Item.useAmmo = AmmoID.Bullet;
      Item.UseSound = SoundID.Item11;
      Item.shoot = ProjectileID.PurificationPowder;
      Item.shootSpeed = 14f;`,
    magic: code`
      Item.useStyle = ItemUseStyleID.Shoot;
      Item.useTime = ${use};
      Item.useAnimation = ${use};
      Item.autoReuse = true;
      Item.noMelee = true;
      Item.DamageType = DamageClass.Magic;
      Item.mana = ${Math.max(4, Math.round(n.power))};
      Item.UseSound = SoundID.Item20;
      Item.shoot = ModContent.ProjectileType<${cls}Projectile>();
      Item.shootSpeed = 11f;`,
  };
  if (kind === "magic") itemDefaults.magic += "Item.staff[Type] = true;\n".replace(/^/, "");
  const ammoSwap =
    kind === "bow" || kind === "gun"
      ? code`
          public override void ModifyShootStats(Player player, ref Vector2 position, ref Vector2 velocity, ref int type, ref int damage, ref float knockback) {
              // Any ${kind === "bow" ? "arrow" : "bullet"} the player loads becomes this weapon's own shot (ammo damage still counts).
              type = ModContent.ProjectileType<${cls}Projectile>();
          }`
      : "";
  const projDefaults =
    kind === "yoyo"
      ? code`
          Projectile.width = 16;
          Projectile.height = 16;
          Projectile.aiStyle = ProjAIStyleID.Yoyo;
          Projectile.friendly = true;
          Projectile.DamageType = DamageClass.MeleeNoSpeed;
          Projectile.penetrate = -1;`
      : code`
          Projectile.CloneDefaults(ProjectileID.${projBase});
          AIType = ProjectileID.${projBase};
          Projectile.friendly = true;
          Projectile.hostile = false;
          Projectile.DamageType = DamageClass.${kind === "magic" ? "Magic" : "Ranged"};`;
  const projStatic =
    kind === "yoyo"
      ? code`
          public override void SetStaticDefaults() {
              ProjectileID.Sets.YoyosLifeTimeMultiplier[Type] = ${f1(3 + n.intensity)};
              ProjectileID.Sets.YoyosMaximumRange[Type] = ${200 + n.radius * 20}f;
              ProjectileID.Sets.YoyosTopSpeed[Type] = ${f1(11 + n.speed * 10)};
          }`
      : "";
  return {
    main: file(
      `Content/Items/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Items
        {
            ${header(c)}
            public class ${cls} : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.${itemArt}}";

                public override void SetStaticDefaults() {
                    ${kind === "yoyo" ? "ItemID.Sets.Yoyo[Type] = true;\nItemID.Sets.GamepadExtraRange[Type] = 15;" : kind === "magic" ? "Item.staff[Type] = true; // hold it like a staff" : "ItemID.Sets.ShimmerTransformToItem[Type] = ItemID.Musket;"}
                }

                public override void SetDefaults() {
                    Item.width = 32;
                    Item.height = 32;
                    Item.damage = ${dmg};
                    Item.knockBack = ${f1(n.power / 3)};
                    Item.value = Item.sellPrice(gold: ${Math.max(1, Math.round(n.power))});
                    Item.rare = ${rare};
                    ${itemDefaults[kind].replace("Item.staff[Type] = true;\n", "")}
                }

                ${ammoSwap}

                public override void AddRecipes() {
                    ${recipe}
                }
            }

            public class ${cls}Projectile : ModProjectile
            {
                public override string Texture => $"Terraria/Images/Projectile_{ProjectileID.${projBase}}";
                ${tuningBlock(c)}

                ${projStatic}

                public override void SetDefaults() {
                    ${projDefaults}
                }

                public override void AI() {
                    if (Main.rand.NextBool(4))
                        ${dustLine(c, "Projectile")}
                    Lighting.AddLight(Projectile.Center, ${c.input.game ? tint(c.fx[0]) : "0.5f, 0.5f, 0.5f"});
                }

                public override void OnHitNPC(NPC target, NPC.HitInfo hit, int damageDone) {
                    Player player = Main.player[Projectile.owner];
                    ${hitFx(c)}
                }
            }
        }`,
    ),
  };
}

