function tmlEnemy(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const t = textOf(input);
  const base = pick(ENEMY_BASE, t, "Zombie");
  const hard = /hardmode|hard mode|late game|endgame/.test(t);
  const spawn =
    base === "CaveBat" || /cave|underground|cavern|deep/.test(t)
      ? "SpawnCondition.Cavern.Chance"
      : base === "BlueSlime"
        ? "SpawnCondition.OverworldDaySlime.Chance"
        : "SpawnCondition.OverworldNightMonster.Chance";
  const splits = c.fx.includes("summon") || /split|hive|swarm|clone/.test(t);
  c.lang.push({ section: "NPCs", key: cls, display: input.modName });
  return {
    main: file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Terraria;
        using Terraria.GameContent.ItemDropRules;
        using Terraria.ID;
        using Terraria.ModLoader;
        using Terraria.ModLoader.Utilities;

        namespace ${mod}.Content.NPCs
        {
            ${header(c)}
            public class ${cls} : ModNPC
            {
                public override string Texture => $"Terraria/Images/NPC_{NPCID.${base}}";
                ${tuningBlock(c)}

                public override void SetStaticDefaults() {
                    Main.npcFrameCount[Type] = Main.npcFrameCount[NPCID.${base}];
                }

                public override void SetDefaults() {
                    NPC.CloneDefaults(NPCID.${base}); // size, sounds and AI style of the base enemy
                    NPC.lifeMax = ${Math.round(n.health / (hard ? 2 : 5))};
                    NPC.damage = ${Math.round(n.power * (hard ? 6 : 3))};
                    NPC.defense = ${Math.round(n.power * (hard ? 2 : 1))};
                    NPC.value = ${Math.round(n.xp * 10)}f;
                    AIType = NPCID.${base};
                    AnimationType = NPCID.${base};
                    NPC.color = new Microsoft.Xna.Framework.Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                }

                public override float SpawnChance(NPCSpawnInfo spawnInfo) {
                    ${hard ? "if (!Main.hardMode)\n    return 0f;" : ""}
                    return ${spawn} * 0.15f;
                }

                public override void OnHitPlayer(Player target, Player.HurtInfo hurtInfo) {
                    ${c.fx.map((e) => `target.AddBuff(${TML_ON_HIT_PLAYER[e]}, Tuning.EffectTicks / 2);`)}
                }

                public override void HitEffect(NPC.HitInfo hit) {
                    for (int i = 0; i < 4; i++)
                        ${dustLine(c, "NPC")}
                }

                ${
                  splits
                    ? code`
                      public override void OnKill() {
                          // Splits on death. Only the server (or single player) spawns enemies; the game syncs them.
                          if (Main.netMode == NetmodeID.MultiplayerClient)
                              return;
                          for (int i = 0; i < 2; i++)
                              NPC.NewNPC(NPC.GetSource_Death(), (int)NPC.Center.X + (i == 0 ? -12 : 12), (int)NPC.Center.Y, NPCID.${base === "BlueSlime" ? "GreenSlime" : base});
                      }`
                    : ""
                }

                public override void ModifyNPCLoot(NPCLoot npcLoot) {
                    npcLoot.Add(ItemDropRule.Common(ItemID.${ENEMY_DROP[c.fx[0]]}, ${Math.max(2, Math.round(1 / n.chance))}));
                }
            }
        }`,
    ),
  };
}

function tmlBoss(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const life = n.health * 12;
  const summonsAdds = c.fx.includes("summon") || /minion|swarm|split|summon/.test(textOf(input));
  c.lang.push({ section: "NPCs", key: cls, display: input.modName });
  c.lang.push({ section: "Items", key: `${cls}Summon`, display: `${input.modName} Lure`, tooltip: `Summons ${clean(input.modName)}` });
  return {
    main: file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.Audio;
        using Terraria.GameContent.ItemDropRules;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.NPCs
        {
            ${header(c)}
            // A three-phase flying boss: stalk, dash, then a faster frenzy below 40% life. AI runs on the server
            // and every phase change sets netUpdate so all players see the same fight.
            public class ${cls} : ModNPC
            {
                public override string Texture => $"Terraria/Images/NPC_{NPCID.EyeofCthulhu}";
                ${tuningBlock(c)}

                private enum Phase { Stalk, Dash, Frenzy }
                private Phase CurrentPhase {
                    get => (Phase)NPC.ai[0];
                    set => NPC.ai[0] = (float)value;
                }
                private ref float Timer => ref NPC.ai[1];

                public override void SetStaticDefaults() {
                    Main.npcFrameCount[Type] = Main.npcFrameCount[NPCID.EyeofCthulhu];
                    NPCID.Sets.MPAllowedEnemies[Type] = true; // lets the summon item work in multiplayer
                    NPCID.Sets.BossBestiaryPriority.Add(Type);
                }

                public override void SetDefaults() {
                    NPC.width = 100;
                    NPC.height = 110;
                    NPC.lifeMax = ${life};
                    NPC.damage = ${Math.round(n.power * 4)};
                    NPC.defense = ${Math.round(n.power)};
                    NPC.knockBackResist = 0f;
                    NPC.noGravity = true;
                    NPC.noTileCollide = true;
                    NPC.boss = true;
                    NPC.npcSlots = 10f;
                    NPC.value = Item.buyPrice(gold: ${Math.max(2, Math.round(n.xp / 8))});
                    NPC.HitSound = SoundID.NPCHit1;
                    NPC.DeathSound = SoundID.NPCDeath1;
                    NPC.aiStyle = -1; // our own AI below
                    NPC.color = new Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                    if (!Main.dedServ)
                        Music = MusicID.Boss1;
                }

                public override void AI() {
                    if (NPC.target < 0 || NPC.target == 255 || Main.player[NPC.target].dead || !Main.player[NPC.target].active)
                        NPC.TargetClosest();
                    Player target = Main.player[NPC.target];
                    if (target.dead || !target.active) {
                        // Nobody left: fly away and despawn instead of camping the spawn point.
                        NPC.velocity.Y -= 0.4f;
                        NPC.EncourageDespawn(10);
                        return;
                    }

                    Timer++;
                    if (CurrentPhase != Phase.Frenzy && NPC.life < NPC.lifeMax * 0.4f) {
                        CurrentPhase = Phase.Frenzy;
                        Timer = 0;
                        SoundEngine.PlaySound(SoundID.Roar, NPC.Center);
                        ${
                          summonsAdds
                            ? code`
                              if (Main.netMode != NetmodeID.MultiplayerClient) {
                                  for (int i = 0; i < 3; i++)
                                      NPC.NewNPC(NPC.GetSource_FromAI(), (int)NPC.Center.X, (int)NPC.Center.Y, NPCID.ServantofCthulhu);
                              }`
                            : ""
                        }
                        NPC.netUpdate = true;
                    }

                    Vector2 toTarget = target.Center - NPC.Center;
                    switch (CurrentPhase) {
                        case Phase.Stalk:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 18)}, 0.05f);
                            if (Timer > ${Math.round(n.cooldown * 50) + 60}) {
                                CurrentPhase = Phase.Dash;
                                Timer = 0;
                                NPC.netUpdate = true;
                            }
                            break;
                        case Phase.Dash:
                            if (Timer == 1)
                                NPC.velocity = toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 42)};
                            NPC.velocity *= 0.975f;
                            if (Timer > 55) {
                                CurrentPhase = Phase.Stalk;
                                Timer = 0;
                                NPC.netUpdate = true;
                            }
                            break;
                        case Phase.Frenzy:
                            NPC.velocity = Vector2.Lerp(NPC.velocity, toTarget.SafeNormalize(Vector2.UnitY) * ${f1(n.speed * 28)}, 0.09f);
                            break;
                    }
                    NPC.rotation = NPC.velocity.ToRotation() - MathHelper.PiOver2;
                    Lighting.AddLight(NPC.Center, ${tint(c.fx[0])});
                }

                public override void FindFrame(int frameHeight) {
                    // The base sheet has a calm and an angry row of three frames each; frenzy uses the angry row.
                    NPC.frameCounter++;
                    int frame = (int)(NPC.frameCounter / 8 % 3) + (CurrentPhase == Phase.Frenzy ? 3 : 0);
                    NPC.frame.Y = frame * frameHeight;
                }

                public override void OnHitPlayer(Player target, Player.HurtInfo hurtInfo) {
                    ${c.fx.map((e) => `target.AddBuff(${TML_ON_HIT_PLAYER[e]}, Tuning.EffectTicks / 2);`)}
                }

                public override void ModifyNPCLoot(NPCLoot npcLoot) {
                    npcLoot.Add(ItemDropRule.Common(ItemID.${ENEMY_DROP[c.fx[0]]}, 1, ${n.radius}, ${n.radius + 8}));
                    npcLoot.Add(ItemDropRule.Common(ItemID.GreaterHealingPotion, 1, 5, 10));
                }

                public override void BossLoot(ref int potionType) {
                    potionType = ItemID.GreaterHealingPotion;
                }
            }

            /// <summary>Use at night to summon ${clean(input.modName)}.</summary>
            public class ${cls}Summon : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.SuspiciousLookingEye}";

                public override void SetStaticDefaults() {
                    ItemID.Sets.SortingPriorityBossSpawns[Type] = 12;
                }

                public override void SetDefaults() {
                    Item.width = 20;
                    Item.height = 20;
                    Item.maxStack = 20;
                    Item.rare = ItemRarityID.Orange;
                    Item.useAnimation = 30;
                    Item.useTime = 30;
                    Item.useStyle = ItemUseStyleID.HoldUp;
                    Item.consumable = true;
                }

                public override bool CanUseItem(Player player) => !Main.dayTime && !NPC.AnyNPCs(ModContent.NPCType<${cls}>());

                public override bool? UseItem(Player player) {
                    if (player.whoAmI == Main.myPlayer) {
                        SoundEngine.PlaySound(SoundID.Roar, player.position);
                        int type = ModContent.NPCType<${cls}>();
                        // Same pattern vanilla summons use: spawn directly in single player, ask the server otherwise.
                        if (Main.netMode != NetmodeID.MultiplayerClient)
                            NPC.SpawnOnPlayer(player.whoAmI, type);
                        else
                            NetMessage.SendData(MessageID.SpawnBossUseLicenseStartEvent, number: player.whoAmI, number2: type);
                    }
                    return true;
                }

                public override void AddRecipes() {
                    CreateRecipe()
                        .AddIngredient(ItemID.Lens, 6)
                        .AddIngredient(ItemID.${ENEMY_DROP[c.fx[0]] === "GoldCoin" ? "FallenStar" : ENEMY_DROP[c.fx[0]]}, 3)
                        .AddTile(TileID.DemonAltar)
                        .Register();
                }
            }
        }`,
    ),
  };
}

function tmlCharacter(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const lines = [
    `I'm ${clean(input.modName, 40)}. ${clean(deriveFeatures(input)[0] ?? "Nice to meet you", 80)}.`,
    "Stay a while. The night is long and the slimes are restless.",
    "If you see me wandering, say hello. I always have a blessing to spare.",
  ];
  c.lang.push({ section: "NPCs", key: cls, display: input.modName });
  return {
    main: file(
      `Content/NPCs/${cls}.cs`,
      code`
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;
        using Terraria.ModLoader.Utilities;

        namespace ${mod}.Content.NPCs
        {
            ${header(c)}
            // A friendly wanderer you can talk to (not a town NPC: no house needed). Its button grants a blessing.
            public class ${cls} : ModNPC
            {
                public override string Texture => $"Terraria/Images/NPC_{NPCID.Guide}";
                ${tuningBlock(c)}

                public override void SetStaticDefaults() {
                    Main.npcFrameCount[Type] = Main.npcFrameCount[NPCID.Guide];
                }

                public override void SetDefaults() {
                    NPC.width = 18;
                    NPC.height = 40;
                    NPC.friendly = true;
                    NPC.townNPC = false;
                    NPC.lifeMax = 250;
                    NPC.defense = 15;
                    NPC.damage = 10;
                    NPC.knockBackResist = 0.5f;
                    NPC.HitSound = SoundID.NPCHit1;
                    NPC.DeathSound = SoundID.NPCDeath1;
                    NPC.aiStyle = NPCAIStyleID.Passive;
                    AIType = NPCID.Bunny;
                    AnimationType = NPCID.Guide;
                }

                public override float SpawnChance(NPCSpawnInfo spawnInfo) {
                    if (NPC.AnyNPCs(Type))
                        return 0f;
                    return SpawnCondition.OverworldDay.Chance * 0.05f;
                }

                public override bool CanChat() => true;

                public override string GetChat() {
                    return Main.rand.Next(3) switch {
                        0 => ${csStr(lines[0])},
                        1 => ${csStr(lines[1])},
                        _ => ${csStr(lines[2])},
                    };
                }

                public override void SetChatButtons(ref string button, ref string button2) {
                    button = "Blessing";
                }

                public override void OnChatButtonClicked(bool firstButton, ref string shopName) {
                    if (!firstButton)
                        return;
                    Player player = Main.LocalPlayer;
                    ${c.fx.map((e) => `player.AddBuff(${TML_SELF_BUFF[e]}, Tuning.EffectTicks * 4);`)}
                    Main.npcChatText = "May it serve you well.";
                }
            }
        }`,
    ),
  };
}

function tmlMount(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const flies = c.fx.includes("flight") || /fly|flying|wing|dragon|glide|hover/.test(textOf(input));
  c.lang.push({ section: "Items", key: `${cls}Item`, display: input.modName, tooltip: "Summons a rideable mount" });
  c.lang.push({ section: "Buffs", key: `${cls}Buff`, display: input.modName, tooltip: "You are riding it" });
  c.extraDocs.push(`The mount itself has no picture yet: add \`Content/Mounts/${cls}_Back.png\` (a 4-frame sheet, like tModLoader's ExampleMount) and it will show up. Until then it rides invisibly; the item and buff use the game's own icons.`);
  return {
    main: file(
      `Content/Mounts/${cls}.cs`,
      code`
        using System.Linq;
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Mounts
        {
            ${header(c)}
            public class ${cls} : ModMount
            {
                ${tuningBlock(c)}

                public override void SetStaticDefaults() {
                    MountData.jumpHeight = ${10 + n.radius};
                    MountData.acceleration = ${f1(0.2 + n.speed / 3)};
                    MountData.jumpSpeed = 6f;
                    MountData.constantJump = true;
                    MountData.heightBoost = 20;
                    MountData.fallDamage = 0f;
                    MountData.runSpeed = ${f1(n.speed * 30)};
                    MountData.dashSpeed = ${f1(n.speed * 24)};
                    MountData.flightTimeMax = ${flies ? 320 : 0};
                    MountData.fatigueMax = 0;
                    MountData.buff = ModContent.BuffType<${cls}Buff>();
                    MountData.spawnDust = ${DUST[c.fx[0]]};
                    MountData.totalFrames = 4;
                    MountData.playerYOffsets = Enumerable.Repeat(20, MountData.totalFrames).ToArray();
                    MountData.xOffset = 13;
                    MountData.yOffset = -12;
                    MountData.playerHeadOffset = 22;
                    MountData.bodyFrame = 3;
                    MountData.standingFrameCount = 4;
                    MountData.standingFrameDelay = 12;
                    MountData.runningFrameCount = 4;
                    MountData.runningFrameDelay = 12;
                    MountData.inAirFrameCount = 1;
                    MountData.inAirFrameDelay = 12;
                    MountData.idleFrameCount = 4;
                    MountData.idleFrameDelay = 12;
                    MountData.idleFrameLoop = true;
                    MountData.swimFrameCount = MountData.inAirFrameCount;
                    MountData.swimFrameDelay = MountData.inAirFrameDelay;
                }

                public override void UpdateEffects(Player player) {
                    // Drift boost: hold Down while moving fast for a short burst of speed.
                    if (player.controlDown && System.Math.Abs(player.velocity.X) > 4f) {
                        player.velocity.X *= 1.02f;
                        if (Main.rand.NextBool(3))
                            Dust.NewDust(player.Bottom, 8, 4, ${DUST[c.fx[0]]});
                    }
                    Lighting.AddLight(player.Center, ${tint(c.fx[0])});
                }
            }

            public class ${cls}Buff : ModBuff
            {
                public override string Texture => $"Terraria/Images/Buff_{BuffID.UnicornMount}";

                public override void SetStaticDefaults() {
                    Main.buffNoTimeDisplay[Type] = true;
                    Main.buffNoSave[Type] = true;
                }

                public override void Update(Player player, ref int buffIndex) {
                    player.mount.SetMount(ModContent.MountType<${cls}>(), player);
                    player.buffTime[buffIndex] = 10;
                }
            }

            public class ${cls}Item : ModItem
            {
                public override string Texture => $"Terraria/Images/Item_{ItemID.BlessedApple}";

                public override void SetDefaults() {
                    Item.width = 20;
                    Item.height = 30;
                    Item.useTime = 20;
                    Item.useAnimation = 20;
                    Item.useStyle = ItemUseStyleID.Swing;
                    Item.value = Item.sellPrice(gold: 3);
                    Item.rare = ItemRarityID.Green;
                    Item.UseSound = SoundID.Item79;
                    Item.noMelee = true;
                    Item.mountType = ModContent.MountType<${cls}>();
                }

                public override void AddRecipes() {
                    CreateRecipe()
                        .AddIngredient(ItemID.Saddle)
                        .AddIngredient(ItemID.SoulofFlight, ${n.interval + 5})
                        .AddTile(TileID.MythrilAnvil)
                        .Register();
                }
            }
        }`,
    ),
  };
}

function tmlWorld(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const tile = ORE_TILE[c.fx[0]];
  c.extraDocs.push("World generation only runs when a NEW world is created. Existing worlds are never changed, which keeps players' saves safe.");
  return {
    main: file(
      `Content/Systems/${cls}System.cs`,
      code`
        using System.Collections.Generic;
        using Terraria;
        using Terraria.ID;
        using Terraria.IO;
        using Terraria.ModLoader;
        using Terraria.WorldBuilding;

        namespace ${mod}.Content.Systems
        {
            ${header(c)}
            // Adds a world-generation step right after the game places its gems and ores ("Shinies").
            public class ${cls}System : ModSystem
            {
                public override void ModifyWorldGenTasks(List<GenPass> tasks, ref double totalWeight) {
                    int index = tasks.FindIndex(pass => pass.Name.Equals("Shinies"));
                    if (index == -1)
                        return; // another mod removed the step; skip rather than guess
                    tasks.Insert(index + 1, new ${cls}Pass(${csStr(clean(input.modName, 40))}, 100f));
                }
            }

            public class ${cls}Pass : GenPass
            {
                public ${cls}Pass(string name, float loadWeight) : base(name, loadWeight) { }

                protected override void ApplyPass(GenerationProgress progress, GameConfiguration configuration) {
                    progress.Message = ${csStr(`Growing ${clean(input.modName, 40)}`)};
                    // Bigger worlds get proportionally more veins.
                    int veins = (int)(Main.maxTilesX * Main.maxTilesY * ${(n.interval * 1e-5).toExponential(2)});
                    for (int k = 0; k < veins; k++) {
                        int x = WorldGen.genRand.Next(100, Main.maxTilesX - 100);
                        int y = WorldGen.genRand.Next((int)Main.rockLayer, Main.maxTilesY - 300);
                        WorldGen.TileRunner(x, y, WorldGen.genRand.Next(${n.radius}, ${n.radius + 4}), WorldGen.genRand.Next(${n.radius + 2}, ${n.radius + 8}), ${tile});
                        progress.Set((double)k / veins);
                    }
                }
            }
        }`,
    ),
  };
}

function tmlMechanic(c: Tml): { main: ModFile } {
  const { input, cls, mod } = c;
  return {
    main: file(
      `Content/Players/${cls}Player.cs`,
      code`
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Players
        {
            ${header(c)}
            // Every few seconds the local player gets a short boon. Runs for the local player only, so it never
            // fights the server or other players.
            public class ${cls}Player : ModPlayer
            {
                ${tuningBlock(c)}
                private int cooldown;

                public override void PostUpdate() {
                    if (Player.whoAmI != Main.myPlayer || Player.dead)
                        return;
                    if (cooldown > 0) {
                        cooldown--;
                        return;
                    }
                    ${c.fx.map((e) => `Player.AddBuff(${TML_SELF_BUFF[e]}, Tuning.EffectTicks);`)}
                    for (int i = 0; i < 10; i++)
                        Dust.NewDust(Player.position, Player.width, Player.height, ${DUST[c.fx[0]]});
                    cooldown = Tuning.CooldownSeconds * 60;
                }
            }
        }`,
    ),
  };
}

function tmlQuest(c: Tml): { main: ModFile } {
  const { input, n, cls, mod } = c;
  const goal = 20 + n.interval * 5;
  const reward = c.fx[0] === "heal" ? "LifeFruit" : c.fx[0] === "fire" ? "HellstoneBar" : "GoldCoin";
  c.extraDocs.push("Quest progress is saved inside the world file under this mod's own key, so removing the mod simply forgets it.");
  return {
    main: file(
      `Content/Systems/${cls}Quest.cs`,
      code`
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.Chat;
        using Terraria.ID;
        using Terraria.Localization;
        using Terraria.ModLoader;
        using Terraria.ModLoader.IO;

        namespace ${mod}.Content.Systems
        {
            ${header(c)}
            // A world-wide hunt: defeat ${goal} enemies at night, then everyone is rewarded. Counting happens on the server
            // (or in single player); progress is stored in the world save.
            public class ${cls}Quest : ModSystem
            {
                public const int Goal = ${goal};
                public static int Progress;
                public static bool Done;

                public override void ClearWorld() {
                    Progress = 0;
                    Done = false;
                }

                public override void SaveWorldData(TagCompound tag) {
                    tag["progress"] = Progress;
                    tag["done"] = Done;
                }

                public override void LoadWorldData(TagCompound tag) {
                    Progress = tag.GetInt("progress");
                    Done = tag.GetBool("done");
                }

                internal static void Announce(string text) {
                    if (Main.netMode == NetmodeID.Server)
                        ChatHelper.BroadcastChatMessage(NetworkText.FromLiteral(text), new Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")}));
                    else
                        Main.NewText(text, new Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")}));
                }
            }

            public class ${cls}QuestCounter : GlobalNPC
            {
                public override void OnKill(NPC npc) {
                    if (Main.netMode == NetmodeID.MultiplayerClient || ${cls}Quest.Done || npc.friendly || npc.CountsAsACritter || npc.SpawnedFromStatue || Main.dayTime)
                        return;
                    ${cls}Quest.Progress++;
                    if (${cls}Quest.Progress % 5 == 0 && ${cls}Quest.Progress < ${cls}Quest.Goal)
                        ${cls}Quest.Announce($"${clean(input.modName, 40)}: {${cls}Quest.Progress}/{${cls}Quest.Goal}");
                    if (${cls}Quest.Progress < ${cls}Quest.Goal)
                        return;
                    ${cls}Quest.Done = true;
                    ${cls}Quest.Announce(${csStr(`${clean(input.modName, 40)} complete! Rewards dropped at every player.`)});
                    for (int i = 0; i < Main.maxPlayers; i++) {
                        Player p = Main.player[i];
                        if (p.active && !p.dead)
                            Item.NewItem(p.GetSource_GiftOrReward(), p.getRect(), ItemID.${reward}, ${reward === "GoldCoin" ? 5 + n.radius : 3});
                    }
                    if (Main.netMode == NetmodeID.Server)
                        NetMessage.SendData(MessageID.WorldData);
                }
            }
        }`,
    ),
  };
}

function tmlInterface(c: Tml): { main: ModFile } {
  const { input, cls, mod } = c;
  c.side = "Client";
  c.extraDocs.push("This is a client-only mod (side = Client): it only changes what you see, so a server does not need it and players can use it anywhere.");
  return {
    main: file(
      `Content/UI/${cls}Overlay.cs`,
      code`
        using System.Collections.Generic;
        using Microsoft.Xna.Framework;
        using Terraria;
        using Terraria.ModLoader;
        using Terraria.UI;

        namespace ${mod}.Content.UI
        {
            ${header(c)}
            // A small heads-up line under the minimap: biome, depth and the nearest boss.
            public class ${cls}Overlay : ModSystem
            {
                public override void ModifyInterfaceLayers(List<GameInterfaceLayer> layers) {
                    int index = layers.FindIndex(layer => layer.Name.Equals("Vanilla: Resource Bars"));
                    if (index == -1)
                        return;
                    layers.Insert(index + 1, new LegacyGameInterfaceLayer(${csStr(`${mod}: Overlay`)}, Draw, InterfaceScaleType.UI));
                }

                private static bool Draw() {
                    Player p = Main.LocalPlayer;
                    if (p.dead || Main.gameMenu)
                        return true;
                    string depth = p.ZoneUnderworldHeight ? "Underworld" : p.ZoneRockLayerHeight ? "Caverns" : p.ZoneDirtLayerHeight ? "Underground" : p.ZoneSkyHeight ? "Sky" : "Surface";
                    string boss = "none";
                    for (int i = 0; i < Main.maxNPCs; i++) {
                        NPC n = Main.npc[i];
                        if (n.active && n.boss) {
                            boss = $"{n.FullName} {(int)(n.Distance(p.Center) / 16f)} tiles";
                            break;
                        }
                    }
                    string text = $"{depth} | Boss: {boss}";
                    Utils.DrawBorderString(Main.spriteBatch, text, new Vector2(Main.screenWidth - 320, 300), new Color(${TINT[c.fx[0]].map((x) => Math.round(x * 255)).join(", ")}));
                    return true;
                }
            }
        }`,
    ),
  };
}

function tmlAudio(c: Tml): { main: ModFile } {
  const { cls, mod } = c;
  c.side = "Client";
  c.extraDocs.push("Uses the game's own soundtrack. To use your own music, add an .ogg under Assets/Music and switch to MusicLoader.GetMusicSlot(Mod, \"Assets/Music/<name>\").");
  return {
    main: file(
      `Content/Scenes/${cls}Scene.cs`,
      code`
        using Terraria;
        using Terraria.ID;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Scenes
        {
            ${header(c)}
            // Changes the music: an eerie night track above ground, a harder track whenever a boss is alive.
            public class ${cls}Scene : ModSceneEffect
            {
                public override int Music => Main.CurrentFrameFlags.AnyActiveBossNPC ? MusicID.OtherworldlyBoss1 : MusicID.OtherworldlyNight;

                public override SceneEffectPriority Priority => SceneEffectPriority.BiomeMedium;

                public override bool IsSceneEffectActive(Player player) => !Main.dayTime && (player.ZoneOverworldHeight || Main.CurrentFrameFlags.AnyActiveBossNPC);
            }
        }`,
    ),
  };
}

function tmlShader(c: Tml): { main: ModFile } {
  const { n, cls, mod } = c;
  c.side = "Client";
  c.extraDocs.push("The colour grade reuses the screen shader the game already ships (the pillar tint), so there is no custom .fx file to compile. It is client-only.");
  return {
    main: file(
      `Content/Scenes/${cls}Scene.cs`,
      code`
        using Terraria;
        using Terraria.Graphics.Effects;
        using Terraria.Graphics.Shaders;
        using Terraria.ModLoader;

        namespace ${mod}.Content.Scenes
        {
            ${header(c)}
            // A night-time colour grade. Registered once on the client; the server never touches graphics.
            public class ${cls}Scene : ModSceneEffect
            {
                private const string Key = ${csStr(`${mod}:${cls}`)};

                public override void Load() {
                    if (Main.dedServ)
                        return;
                    Filters.Scene[Key] = new Filter(new ScreenShaderData("FilterMiniTower").UseColor(${tint(c.fx[0])}).UseOpacity(${f1(Math.min(0.6, 0.25 + n.intensity / 4))}), EffectPriority.Medium);
                }

                public override SceneEffectPriority Priority => SceneEffectPriority.Environment;

                public override bool IsSceneEffectActive(Player player) => !Main.dayTime || Main.raining;

                public override void SpecialVisuals(Player player, bool isActive) {
                    player.ManageSpecialBiomeVisuals(Key, isActive);
                }
            }
        }`,
    ),
  };
}

function tmlMain(c: Tml): ModFile {
  const k = c.input.category.key;
  const t = textOf(c.input);
  if (k === "weapons" || k === "magic") return tmlWeapon(c).main;
  if (k === "items") return /\b(swords?|blades?|bows?|guns?|staffs?|wands?|yoyos?|weapon)\b/.test(t) ? tmlWeapon(c).main : tmlAccessory(c).main;
  if (k === "creatures") return /\b(boss|king|queen|lord|titan|monarch|phase|overlord|colossus)\b/.test(t) ? tmlBoss(c).main : tmlEnemy(c).main;
  if (k === "characters") return tmlCharacter(c).main;
  if (k === "vehicles") return tmlMount(c).main;
  if (k === "worlds") return tmlWorld(c).main;
  if (k === "quests") return tmlQuest(c).main;
  if (k === "interface") return tmlInterface(c).main;
  if (k === "audio") return tmlAudio(c).main;
  if (k === "shaders") return tmlShader(c).main;
  return tmlMechanic(c).main;
}

/** Minimal hjson writer for tModLoader 1.4.4 localization (file prefix = Mods.<mod>). */
function hjson(c: Tml): string {
  const bySection = new Map<string, Tml["lang"]>();
  for (const l of c.lang) bySection.set(l.section, [...(bySection.get(l.section) ?? []), l]);
  const q = (s: string) => (/^[\w .,'!?()-]*$/.test(s) && !/^\s|\s$/.test(s) && s ? s : JSON.stringify(s));
  const out: string[] = ["# Display names and tooltips (tModLoader 1.4.4 localization). tModLoader adds missing keys when you build."];
  for (const [section, rows] of bySection) {
    out.push(`${section}: {`);
    for (const r of rows) {
      out.push(`\t${r.key}: {`);
      out.push(`\t\tDisplayName: ${q(r.display)}`);
      if (r.tooltip !== undefined) out.push(r.tooltip.includes("\n") ? `\t\tTooltip:\n\t\t\t'''\n${r.tooltip.split("\n").map((x) => `\t\t\t${x}`).join("\n")}\n\t\t\t'''` : `\t\t${section === "Buffs" ? "Description" : "Tooltip"}: ${q(r.tooltip)}`);
      out.push("\t}");
    }
    out.push("}");
  }
  if (c.config) {
    out.push("Configs: {", `\t${c.cls}Config: {`, `\t\tDisplayName: ${q(`${c.input.modName} settings`)}`);
    for (const [k, label, tip] of CONFIG_FIELDS) out.push(`\t\t${k}: {`, `\t\t\tLabel: ${label}`, `\t\t\tTooltip: ${tip}`, "\t\t}");
    out.push("\t}", "}");
  }
  return out.join("\n") + "\n";
}

const CONFIG_FIELDS: [string, string, string][] = [
  ["Power", "Effect power", "Multiplies effect damage and healing"],
  ["EffectTicks", "Effect length (ticks)", "60 ticks is one second"],
  ["RadiusTiles", "Effect radius (tiles)", "How far area effects reach"],
  ["Chance", "Proc chance", "Chance for chance-based effects, 0 to 1"],
  ["CooldownSeconds", "Cooldown (seconds)", "Time between repeating effects"],
];

function tmlConfig(c: Tml): ModFile {
  const scope = c.side === "Client" ? "ClientSide" : "ServerSide";
  return file(
    `Common/${c.cls}Config.cs`,
    code`
      using System.ComponentModel;
      using Terraria.ModLoader.Config;

      namespace ${c.mod}.Common
      {
          // ${scope === "ServerSide" ? "Server-side: the host's values are sent to every player when they join." : "Client-side: each player sets their own."}
          public class ${c.cls}Config : ModConfig
          {
              public override ConfigScope Mode => ConfigScope.${scope};

              [DefaultValue(${f1(c.t.power)})]
              [Range(0.25f, 3f)]
              public float Power;

              [DefaultValue(${c.t.effectTicks})]
              [Range(60, 1800)]
              public int EffectTicks;

              [DefaultValue(${c.t.radiusTiles})]
              [Range(2, 40)]
              public int RadiusTiles;

              [DefaultValue(${f1(c.t.chance)})]
              [Range(0f, 1f)]
              public float Chance;

              [DefaultValue(${c.t.cooldownSeconds})]
              [Range(1, 120)]
              public int CooldownSeconds;
          }
      }`,
  );
}

function manifest(o: {
  input: TemplateInput;
  flavor: TerrariaFlavor;
  internalName: string;
  version: string;
  side: string;
  playersInstall: boolean;
  entry: string;
  output: string;
  installPath: string;
  target: Record<string, string>;
  dependencies?: string[];
  permissions?: string[];
  commands?: string[];
}): ModFile {
  return file(
    "cyrus.mod.json",
    JSON.stringify(
      {
        schema: 1,
        game: "terraria",
        flavor: o.flavor,
        name: o.input.modName,
        internalName: o.internalName,
        version: o.version,
        target: o.target,
        side: o.side,
        playersInstall: o.playersInstall,
        entry: o.entry,
        output: o.output,
        installPath: o.installPath,
        dependencies: o.dependencies ?? [],
        ...(o.permissions ? { permissions: o.permissions } : {}),
        ...(o.commands ? { commands: o.commands } : {}),
        generator: { by: "Cyrus", model: MODEL_NAME[o.input.model], category: o.input.category.key },
      },
      null,
      2,
    ) + "\n",
  );
}

export function terrariaTModLoader(input: TemplateInput): Built {
  const { cls } = identity(input.modName);
  const n = numbers(input);
  const mod = /Mod$/.test(cls) ? cls : `${cls}Mod`;
  const c: Tml = {
    input,
    n,
    t: tuning(n),
    fx: effectsFor(input).map((e) => e.key),
    cls,
    mod,
    model: MODEL_NAME[input.model],
    config: input.model !== "katara",
    side: "Both",
    lang: [],
    extraDocs: [],
  };
  const main = tmlMain(c); // may switch c.side and fill c.lang / c.extraDocs
  const version = `${input.version}.0`;
  const build = file(
    "build.txt",
    code`
      displayName = ${clean(input.modName, 60)}
      author = Made with Cyrus
      version = ${version}
      side = ${c.side}
      hideCode = false
      hideResources = false
      includeSource = true
      buildIgnore = *.csproj, *.user, obj\\*, bin\\*, .vs\\*, cyrus.mod.json, README.md, CHANGELOG.md
      `,
  );
  const man = manifest({
    input,
    flavor: "tmodloader",
    internalName: mod,
    version,
    side: c.side === "Client" ? "client" : "both",
    playersInstall: true,
    entry: main.path,
    output: `${mod}.tmod`,
    installPath: "tModLoader/Mods (enable it in enabled.json)",
    target: { terraria: TML_TARGET.terraria, loader: "tModLoader", loaderVersion: TML_TARGET.month, release: TML_TARGET.release, dotnet: TML_TARGET.dotnet },
  });
  const modClass = file(
    `${mod}.cs`,
    code`
      using Terraria.ModLoader;

      namespace ${mod}
      {
          // The mod's entry point. The folder (and namespace) must be named ${mod} for tModLoader to build it.
          public class ${mod} : Mod
          {
          }
      }`,
  );
  const csproj = file(
    `${mod}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">
        <!-- tModLoader writes tModLoader.targets into your ModSources folder; this file is only needed for IDEs. -->
        <Import Project="..\\tModLoader.targets" />
        <PropertyGroup>
          <AssemblyName>${mod}</AssemblyName>
          <LangVersion>latest</LangVersion>
        </PropertyGroup>
      </Project>
      `,
  );
  const description = file(
    "description.txt",
    `${clean(input.modName, 60)}\n\n${deriveFeatures(input).map((f) => `- ${f}`).join("\n")}\n\n${c.side === "Client" ? "Client-side: only you need it." : "Everyone on the server needs it; the server sends it to players when they join."}\n\nMade with Cyrus.\n`,
  );
  const l10n = file(`Localization/en-US_Mods.${mod}.hjson`, hjson(c));
  const test = file(
    `Common/${cls}SelfCheck.cs`,
    code`
      using Terraria.ModLoader;

      namespace ${mod}.Common
      {
          // Load-time self check: tModLoader mods have no test runner, so this logs a warning in client.log /
          // server.log if a setting is out of the range the mod was balanced for. It never changes anything.
          public class ${cls}SelfCheck : ModSystem
          {
              public override void PostSetupContent() {
                  var cfg = ModContent.GetInstance<${cls}Config>();
                  if (cfg == null)
                      return;
                  if (cfg.Power > 2.5f)
                      Mod.Logger.Warn("Power is above 2.5: effects may out-scale endgame gear.");
                  if (cfg.EffectTicks > 1200)
                      Mod.Logger.Warn("Effects longer than 20 seconds can feel permanent in multiplayer.");
                  if (cfg.Chance > 0.6f)
                      Mod.Logger.Warn("Proc chance above 60% makes chance effects nearly constant.");
              }
          }
      }`,
  );
  // First three files must build and load on their own (Katara ships only those): content, build.txt, manifest.
  return { files: [main, build, man, modClass, csproj, description], config: c.config ? tmlConfig(c) : undefined, l10n, test, ...{ notes: c.extraDocs } } as Built;
}

/* ═════════════════════════ TShock plugin ═════════════════════════ */

type TsMode = "power" | "enchant" | "rewards" | "welcome" | "bossrush";
function tshockMode(input: TemplateInput): TsMode {
  const t = textOf(input);
  if (/boss ?rush|gauntlet|boss waves?|arena/.test(t)) return "bossrush";
  if (/welcome|greet|join|motd|first[- ]time|starter|kit|broadcast|announce|auto[- ]?message/.test(t)) return "welcome";
  if (/reward|bounty|loot|drop|coins?|gold|kill(s|ing)?\b|defeat|boss dies|economy/.test(t)) return "rewards";
  if (/swords?|blades?|weapons?|bows?|guns?|staffs?|enchant|imbue|holding|hits? with|on hit/.test(t) || input.category.key === "weapons" || input.category.key === "magic") return "enchant";
  return "power";
}

/** Server-side effect on `npc` struck by/near `ply` (TSPlayer). `dmg` = int base damage in scope. */
function tsEffect(e: EffectKey): string {
  const buff = (id: string) => `npc.AddBuff(BuffID.${id}, settings.EffectTicks);\nSyncBuffs(npc);`;
  switch (e) {
    case "frost":
      return buff("Frostburn2");
    case "fire":
      return buff("OnFire3");
    case "poison":
      return buff("Venom");
    case "void":
      return buff("ShadowFlame");
    case "lunar":
      return `if (!Main.dayTime) {\n    ${buff("Daybreak").replace("\n", "\n    ")}\n}`;
    case "storm":
      return code`
        // Chain lightning to up to three other enemies nearby.
        int arcs = 0;
        for (int i = 0; i < Main.maxNPCs && arcs < 3; i++) {
            NPC other = Main.npc[i];
            if (!other.active || other.whoAmI == npc.whoAmI || other.friendly || other.dontTakeDamage || other.townNPC)
                continue;
            if (Vector2.Distance(other.Center, npc.Center) > settings.RadiusTiles * 16f)
                continue;
            TSPlayer.Server.StrikeNPC(other.whoAmI, System.Math.Max(1, (int)(dmg * 0.5f * settings.Power)), 0f, 0);
            arcs++;
        }`;
    case "blink":
      return "if (Main.rand.NextDouble() < settings.Chance)\n    ply.Teleport(npc.position.X, npc.position.Y - 48f);";
    case "heal":
      return "ply.Heal(System.Math.Max(1, (int)(dmg * 0.05f * settings.Power)));";
    case "summon":
      return code`
        // Echoes: two extra spectral hits on the same enemy.
        if (Main.rand.NextDouble() < settings.Chance) {
            for (int i = 0; i < 2 && npc.active; i++)
                TSPlayer.Server.StrikeNPC(npc.whoAmI, System.Math.Max(1, (int)(dmg * 0.35f * settings.Power)), 0f, 0);
        }`;
    case "flight":
      return "ply.SetBuff(BuffID.Featherfall, settings.EffectTicks);";
    case "auto":
      return `ply.SetBuff(BuffID.Mining, settings.EffectTicks);\n${buff("Midas")}`;
    case "neon":
      return `ply.SetBuff(BuffID.Shine, settings.EffectTicks);\n${buff("Ichor")}`;
  }
}

interface Ts {
  input: TemplateInput;
  n: Nums;
  t: Tuning;
  fx: EffectKey[];
  cls: string;
  cmd: string;
  perm: string;
  mode: TsMode;
  name: string;
}

const BOSS_ORDER = ["KingSlime", "EyeofCthulhu", "EaterofWorldsHead", "QueenBee", "SkeletronHead", "Deerclops"];
const KIT: [RegExp, [string, number][]][] = [
  [/frost|ice|snow/, [["IceBlade", 1], ["HandWarmer", 1], ["LesserHealingPotion", 10]]],
  [/fire|flame|lava/, [["FieryGreatsword", 1], ["ObsidianSkinPotion", 3], ["LesserHealingPotion", 10]]],
];
const DEFAULT_KIT: [string, number][] = [["CopperShortsword", 1], ["Torch", 30], ["LesserHealingPotion", 10], ["Rope", 50]];

function tsSettings(s: Ts): { fields: string[]; json: Record<string, unknown> } {
  const base: [string, string, unknown][] = [
    ["float", "Power", s.t.power],
    ["int", "EffectTicks", s.t.effectTicks],
    ["int", "RadiusTiles", s.t.radiusTiles],
    ["double", "Chance", s.t.chance],
    ["int", "CooldownSeconds", s.t.cooldownSeconds],
  ];
  const extra: [string, string, unknown][] = [];
  const t = textOf(s.input);
  if (s.mode === "enchant") extra.push(["List<int>", "EnchantedItems", "ENCHANT"]);
  if (s.mode === "rewards") extra.push(["bool", "BossesOnly", !/any|every|all (enemies|kills)|each kill/.test(t)], ["int", "RewardItem", "ITEM:GoldCoin"], ["int", "RewardStack", 2 + (s.n.radius % 4)], ["bool", "Broadcast", true]);
  if (s.mode === "welcome") extra.push(["string", "WelcomeMessage", `Welcome to the server, {0}! Type /${s.cmd} for help.`], ["List<int[]>", "FirstJoinKit", "KIT"], ["int", "BroadcastMinutes", 10 + s.n.interval], ["List<string>", "Broadcasts", ["Be kind, build big.", "Bosses hit harder at night.", `Need help? Try /${s.cmd}.`]]);
  if (s.mode === "bossrush") extra.push(["List<int>", "Bosses", "BOSSES"], ["int", "SecondsBetween", 10], ["int", "RewardItem", "ITEM:GoldCoin"], ["int", "RewardStack", 5]);
  const kit = pick(KIT.map(([re, k]) => [re, JSON.stringify(k)] as [RegExp, string]), t, JSON.stringify(DEFAULT_KIT));
  const csInit = (type: string, v: unknown): string => {
    if (v === "ENCHANT") return `new List<int> { ItemID.${pick(MELEE_ART, t, "Muramasa")}, ItemID.${pick(BOW_ART, t, "PlatinumBow")}, ItemID.${pick(STAFF_SAFE, t, "AmethystStaff")} }`;
    if (v === "BOSSES") return `new List<int> { ${BOSS_ORDER.map((b) => `NPCID.${b}`).join(", ")} }`;
    if (v === "KIT") return `new List<int[]> { ${(JSON.parse(kit) as [string, number][]).map(([id, q]) => `new[] { ItemID.${id}, ${q} }`).join(", ")} }`;
    if (typeof v === "string" && v.startsWith("ITEM:")) return `ItemID.${v.slice(5)}`;
    if (type === "float") return f1(v as number);
    if (type === "double") return String(v);
    if (type === "List<string>") return `new List<string> { ${(v as string[]).map(csStr).join(", ")} }`;
    return typeof v === "string" ? csStr(v) : String(v);
  };
  const all = [...base, ...extra];
  return {
    fields: all.map(([type, name, v]) => `public ${type} ${name} { get; set; } = ${csInit(type, v)};`),
    json: Object.fromEntries(all.map(([, name, v]) => [name, typeof v === "string" && /^(ENCHANT|BOSSES|KIT|ITEM:)/.test(v) ? `(game ids, written by the plugin on first start)` : v])),
  };
}

function tsBody(s: Ts): { fields: string[]; init: string[]; dispose: string[]; methods: string; commands: string[] } {
  const fx = s.fx.map(tsEffect).join("\n");
  const effectMethod = code`
    /// <summary>Applies this mod's effect to one enemy on behalf of a player. Server-side; the game syncs the result.</summary>
    private void ApplyEffect(TSPlayer ply, NPC npc, int dmg)
    {
        if (applying)
            return; // our own strikes below fire the strike hook again; never recurse
        applying = true;
        try
        {
            ${fx}
        }
        finally
        {
            applying = false;
        }
    }`;
  const help = `/${s.cmd} - ${clean(deriveFeatures(s.input)[0] ?? s.input.modName, 80)}`;
  switch (s.mode) {
    case "power":
      return {
        fields: ["private readonly Dictionary<int, DateTime> lastUse = new Dictionary<int, DateTime>();"],
        init: [`Commands.ChatCommands.Add(new Command(UsePermission, OnCommand, ${csStr(s.cmd)}) { HelpText = ${csStr(help)}, AllowServer = false });`, "ServerApi.Hooks.ServerLeave.Register(this, OnLeave);"],
        dispose: ["Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnCommand);", "ServerApi.Hooks.ServerLeave.Deregister(this, OnLeave);"],
        commands: [s.cmd],
        methods: code`
          private void OnCommand(CommandArgs args)
          {
              TSPlayer ply = args.Player;
              if (!ply.RealPlayer || ply.Dead)
              {
                  ply.SendErrorMessage("You need to be alive in the world to use this.");
                  return;
              }
              if (lastUse.TryGetValue(ply.Index, out DateTime last) && (DateTime.UtcNow - last).TotalSeconds < settings.CooldownSeconds)
              {
                  ply.SendErrorMessage($"Recharging: {settings.CooldownSeconds - (int)(DateTime.UtcNow - last).TotalSeconds}s left.");
                  return;
              }
              lastUse[ply.Index] = DateTime.UtcNow;

              int hits = 0;
              int dmg = (int)(20 * settings.Power);
              for (int i = 0; i < Main.maxNPCs; i++)
              {
                  NPC npc = Main.npc[i];
                  if (!npc.active || npc.friendly || npc.townNPC || npc.dontTakeDamage || Vector2.Distance(npc.Center, ply.TPlayer.Center) > settings.RadiusTiles * 16f)
                      continue;
                  TSPlayer.Server.StrikeNPC(npc.whoAmI, dmg, 4f, npc.Center.X < ply.TPlayer.Center.X ? -1 : 1);
                  ApplyEffect(ply, npc, dmg);
                  hits++;
              }
              ply.SendSuccessMessage(hits == 0 ? "Nothing in range." : $"${clean(s.input.modName, 40)} hit {hits} {(hits == 1 ? "enemy" : "enemies")}.");
          }

          private void OnLeave(LeaveEventArgs args) => lastUse.Remove(args.Who);

          ${effectMethod}`,
      };
    case "enchant":
      return {
        fields: [],
        init: ["ServerApi.Hooks.NpcStrike.Register(this, OnStrike);"],
        dispose: ["ServerApi.Hooks.NpcStrike.Deregister(this, OnStrike);"],
        commands: [],
        methods: code`
          /// <summary>When a player with permission hits an enemy while holding one of the enchanted items, add the effect.</summary>
          private void OnStrike(NpcStrikeEventArgs args)
          {
              if (args.Handled || applying || args.Player == null || args.Npc == null || !args.Npc.active)
                  return;
              TSPlayer ply = TShock.Players[args.Player.whoAmI];
              if (ply == null || !ply.Active || !ply.HasPermission(UsePermission))
                  return;
              if (!settings.EnchantedItems.Contains(args.Player.HeldItem.type))
                  return;
              ApplyEffect(ply, args.Npc, args.Damage);
          }

          ${effectMethod}`,
      };
    case "rewards":
      return {
        fields: ["private readonly Dictionary<int, DateTime> recentBossKills = new Dictionary<int, DateTime>();"],
        init: ["ServerApi.Hooks.NpcKilled.Register(this, OnKilled);"],
        dispose: ["ServerApi.Hooks.NpcKilled.Deregister(this, OnKilled);"],
        commands: [],
        methods: code`
          private void OnKilled(NpcKilledEventArgs args)
          {
              NPC npc = args.npc;
              if (npc == null || npc.friendly || npc.townNPC || npc.SpawnedFromStatue)
                  return;
              if (settings.BossesOnly && !npc.boss)
                  return;
              if (npc.boss)
              {
                  // Multi-part bosses report a kill per segment: reward once per boss type per 30 seconds.
                  if (recentBossKills.TryGetValue(npc.type, out DateTime t) && (DateTime.UtcNow - t).TotalSeconds < 30)
                      return;
                  recentBossKills[npc.type] = DateTime.UtcNow;
                  foreach (TSPlayer p in TShock.Players)
                  {
                      if (p != null && p.Active && p.RealPlayer && p.HasPermission(UsePermission))
                          p.GiveItem(settings.RewardItem, settings.RewardStack);
                  }
                  if (settings.Broadcast)
                      TShock.Utils.Broadcast($"{npc.FullName} was defeated! Everyone online gets a reward.", ${TINT[s.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
                  return;
              }
              // Regular enemy: reward the last player who hit it.
              int who = npc.lastInteraction;
              if (who < 0 || who >= Main.maxPlayers)
                  return;
              TSPlayer killer = TShock.Players[who];
              if (killer != null && killer.Active && killer.HasPermission(UsePermission) && Main.rand.NextDouble() < settings.Chance)
                  killer.GiveItem(settings.RewardItem, 1);
          }`,
      };
    case "welcome":
      return {
        fields: ["private HashSet<string> seen = new HashSet<string>();", "private int ticks;", "private int nextBroadcast;"],
        init: [
          "LoadSeen();",
          "ServerApi.Hooks.NetGreetPlayer.Register(this, OnGreet);",
          "ServerApi.Hooks.GameUpdate.Register(this, OnUpdate);",
          `Commands.ChatCommands.Add(new Command(UsePermission, OnHelp, ${csStr(s.cmd)}) { HelpText = ${csStr(`/${s.cmd} - server tips`)} });`,
        ],
        dispose: ["ServerApi.Hooks.NetGreetPlayer.Deregister(this, OnGreet);", "ServerApi.Hooks.GameUpdate.Deregister(this, OnUpdate);", "Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnHelp);"],
        commands: [s.cmd],
        methods: code`
          private static string SeenPath => Path.Combine(TShock.SavePath, ${csStr(`${s.cls}.seen.json`)});

          private void LoadSeen()
          {
              try
              {
                  if (File.Exists(SeenPath))
                      seen = JsonConvert.DeserializeObject<HashSet<string>>(File.ReadAllText(SeenPath)) ?? new HashSet<string>();
              }
              catch (Exception ex)
              {
                  TShock.Log.ConsoleError($"[${s.name}] Could not read {SeenPath}: {ex.Message}");
              }
          }

          private void OnGreet(GreetPlayerEventArgs args)
          {
              TSPlayer ply = TShock.Players[args.Who];
              if (ply == null || !ply.RealPlayer)
                  return;
              ply.SendInfoMessage(string.Format(settings.WelcomeMessage, ply.Name));
              // First visit only: keyed by character name, remembered in this plugin's own file.
              if (!seen.Add(ply.Name))
                  return;
              foreach (int[] entry in settings.FirstJoinKit)
              {
                  if (entry.Length == 2 && entry[0] > 0 && entry[1] > 0)
                      ply.GiveItem(entry[0], entry[1]);
              }
              ply.SendSuccessMessage("A starter kit has been dropped at your feet.");
              try
              {
                  File.WriteAllText(SeenPath, JsonConvert.SerializeObject(seen));
              }
              catch (Exception ex)
              {
                  TShock.Log.ConsoleError($"[${s.name}] Could not save {SeenPath}: {ex.Message}");
              }
          }

          private void OnUpdate(EventArgs args)
          {
              // GameUpdate runs 60 times a second: count updates instead of starting a timer thread.
              if (settings.Broadcasts.Count == 0 || settings.BroadcastMinutes <= 0 || ++ticks < settings.BroadcastMinutes * 3600)
                  return;
              ticks = 0;
              TShock.Utils.Broadcast(settings.Broadcasts[nextBroadcast++ % settings.Broadcasts.Count], ${TINT[s.fx[0]].map((x) => Math.round(x * 255)).join(", ")});
          }

          private void OnHelp(CommandArgs args)
          {
              foreach (string line in settings.Broadcasts)
                  args.Player.SendInfoMessage(line);
          }`,
      };
    case "bossrush":
      return {
        fields: ["private int stage = -1;", "private int waitTicks;", "private TSPlayer host;"],
        init: [
          `Commands.ChatCommands.Add(new Command(AdminPermission, OnCommand, ${csStr(s.cmd)}) { HelpText = ${csStr(`/${s.cmd} start|stop|status - fight the bosses one after another`)}, AllowServer = false });`,
          "ServerApi.Hooks.NpcKilled.Register(this, OnKilled);",
          "ServerApi.Hooks.GameUpdate.Register(this, OnUpdate);",
        ],
        dispose: ["Commands.ChatCommands.RemoveAll(c => c.CommandDelegate == OnCommand);", "ServerApi.Hooks.NpcKilled.Deregister(this, OnKilled);", "ServerApi.Hooks.GameUpdate.Deregister(this, OnUpdate);"],
        commands: [s.cmd],
        methods: code`
          private bool Running => stage >= 0;

          private void OnCommand(CommandArgs args)
          {
              string sub = args.Parameters.Count > 0 ? args.Parameters[0].ToLowerInvariant() : "status";
              switch (sub)
              {
                  case "start":
                      if (Running)
                      {
                          args.Player.SendErrorMessage("A boss rush is already running.");
                          return;
                      }
                      if (settings.Bosses.Count == 0)
                      {
                          args.Player.SendErrorMessage("No bosses configured.");
                          return;
                      }
                      host = args.Player;
                      stage = 0;
                      waitTicks = 60 * 3;
                      TShock.Utils.Broadcast($"Boss rush started by {host.Name}: {settings.Bosses.Count} bosses incoming!", 255, 120, 80);
                      break;
                  case "stop":
                      stage = -1;
                      TShock.Utils.Broadcast("Boss rush stopped.", 200, 200, 200);
                      break;
                  default:
                      args.Player.SendInfoMessage(Running ? $"Boss {stage + 1} of {settings.Bosses.Count}." : $"No boss rush running. /${s.cmd} start");
                      break;
              }
          }

          private void OnUpdate(EventArgs args)
          {
              if (!Running || waitTicks <= 0 || --waitTicks > 0)
                  return;
              if (host == null || !host.Active || host.Dead)
              {
                  stage = -1;
                  TShock.Utils.Broadcast("Boss rush ended: the host left or died.", 200, 200, 200);
                  return;
              }
              int type = settings.Bosses[stage];
              TSPlayer.Server.SpawnNPC(type, Lang.GetNPCNameValue(type), 1, host.TileX, host.TileY - 20, 30, 10);
          }

          private void OnKilled(NpcKilledEventArgs args)
          {
              if (!Running || args.npc == null || !args.npc.boss || stage >= settings.Bosses.Count || args.npc.type != settings.Bosses[stage])
                  return;
              stage++;
              if (stage >= settings.Bosses.Count)
              {
                  stage = -1;
                  TShock.Utils.Broadcast("Boss rush complete! Rewards for everyone online.", 120, 255, 140);
                  foreach (TSPlayer p in TShock.Players)
                  {
                      if (p != null && p.Active && p.RealPlayer)
                          p.GiveItem(settings.RewardItem, settings.RewardStack);
                  }
                  return;
              }
              waitTicks = settings.SecondsBetween * 60;
              TShock.Utils.Broadcast($"Next boss in {settings.SecondsBetween} seconds ({stage + 1}/{settings.Bosses.Count}).", 255, 200, 80);
          }`,
      };
  }
}

export function terrariaTShock(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const n = numbers(input);
  const mode = tshockMode(input);
  const cmd = (snake.replace(/_/g, "").slice(0, 16) || "cyrus").toLowerCase();
  const s: Ts = { input, n, t: tuning(n), fx: effectsFor(input).map((e) => e.key), cls, cmd, perm: `cyrus.${cmd}`, mode, name: clean(input.modName, 60) };
  const body = tsBody(s);
  const settings = tsSettings(s);
  const usesStrike = /TSPlayer\.Server\.StrikeNPC|SyncBuffs/.test(body.methods);
  const version = `${input.version}.0.0`;
  const permissions = mode === "bossrush" ? [`${s.perm}.admin`] : [`${s.perm}.use`];
  const plugin = file(
    `${cls}.cs`,
    code`
      // ${s.name}: a TShock server plugin made with Cyrus (${MODEL_NAME[input.model]}), v${input.version}.
      // Target: TShock ${TSHOCK_TARGET.tshock} (Terraria ${TSHOCK_TARGET.terraria}), TerrariaServerAPI ${TSHOCK_TARGET.tsapi}, .NET 9.
      // Runs on the server only: players join with the normal game and install nothing.
      using System;
      using System.Collections.Generic;
      using System.IO;
      using Microsoft.Xna.Framework;
      using Newtonsoft.Json;
      using Terraria;
      using Terraria.ID;
      using TerrariaApi.Server;
      using TShockAPI;
      using TShockAPI.Hooks;

      namespace Cyrus.${cls}
      {
          [ApiVersion(2, 1)]
          public class ${cls}Plugin : TerrariaPlugin
          {
              public override string Name => ${csStr(s.name)};
              public override Version Version => new Version(${version.split(".").join(", ")});
              public override string Author => "Made with Cyrus";
              public override string Description => ${csStr(clean(deriveFeatures(input).join(". "), 200))};

              public const string UsePermission = ${csStr(`${s.perm}.use`)};
              public const string AdminPermission = ${csStr(`${s.perm}.admin`)};

              /// <summary>This plugin's settings file, inside TShock's own folder (never a hard-coded path).</summary>
              private static string ConfigPath => Path.Combine(TShock.SavePath, ${csStr(`${cls}.json`)});

              private Settings settings = new Settings();
              ${usesStrike || mode === "enchant" || mode === "power" ? "[ThreadStatic] private static bool applying;" : ""}
              ${body.fields}

              public ${cls}Plugin(Main game) : base(game)
              {
              }

              public override void Initialize()
              {
                  LoadSettings();
                  GeneralHooks.ReloadEvent += OnReload;
                  ${body.init}
              }

              protected override void Dispose(bool disposing)
              {
                  if (disposing)
                  {
                      GeneralHooks.ReloadEvent -= OnReload;
                      ${body.dispose}
                  }
                  base.Dispose(disposing);
              }

              ${body.methods}

              ${
                usesStrike
                  ? code`
                    /// <summary>Tell every player about the enemy's new debuffs.</summary>
                    private static void SyncBuffs(NPC npc) => NetMessage.SendData((int)PacketTypes.NpcUpdateBuff, -1, -1, null, npc.whoAmI);`
                  : ""
              }

              private void OnReload(ReloadEventArgs args)
              {
                  LoadSettings();
                  args.Player?.SendSuccessMessage(${csStr(`[${s.name}] settings reloaded.`)});
              }

              /// <summary>Reads the settings file, writing the defaults the first time. A broken file never stops the server.</summary>
              private void LoadSettings()
              {
                  try
                  {
                      if (File.Exists(ConfigPath))
                          settings = JsonConvert.DeserializeObject<Settings>(File.ReadAllText(ConfigPath)) ?? new Settings();
                      else
                          File.WriteAllText(ConfigPath, JsonConvert.SerializeObject(settings, Formatting.Indented));
                      settings.Clamp();
                  }
                  catch (Exception ex)
                  {
                      settings = new Settings();
                      TShock.Log.ConsoleError($"[${s.name}] Could not read {ConfigPath}, using defaults: {ex.Message}");
                  }
              }

              public class Settings
              {
                  ${settings.fields}

                  /// <summary>Keeps hand-edited values inside safe limits.</summary>
                  public void Clamp()
                  {
                      Power = Math.Clamp(Power, 0.1f, 5f);
                      EffectTicks = Math.Clamp(EffectTicks, 30, 3600);
                      RadiusTiles = Math.Clamp(RadiusTiles, 1, 60);
                      Chance = Math.Clamp(Chance, 0d, 1d);
                      CooldownSeconds = Math.Clamp(CooldownSeconds, 0, 3600);
                  }
              }
          }
      }`,
  );
  const csproj = file(
    `${cls}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">
        <!-- Build: dotnet build -c Release  (needs the .NET 9 SDK). Output: bin/Release/${TSHOCK_TARGET.dotnet}/${cls}.dll -->
        <PropertyGroup>
          <TargetFramework>${TSHOCK_TARGET.dotnet}</TargetFramework>
          <AssemblyName>${cls}</AssemblyName>
          <RootNamespace>Cyrus.${cls}</RootNamespace>
          <Version>${version}</Version>
          <Nullable>disable</Nullable>
          <ImplicitUsings>disable</ImplicitUsings>
          <LangVersion>latest</LangVersion>
          <EnableDynamicLoading>true</EnableDynamicLoading>
        </PropertyGroup>
        <ItemGroup>
          <!-- TShock's own NuGet package (GPL-3.0). The server already has these files, so they are not copied out. -->
          <PackageReference Include="${TSHOCK_TARGET.nuget.id}" Version="${TSHOCK_TARGET.nuget.version}" ExcludeAssets="runtime" PrivateAssets="all" />
        </ItemGroup>
      </Project>
      `,
  );
  const man = manifest({
    input,
    flavor: "tshock",
    internalName: cls,
    version,
    side: "server",
    playersInstall: false,
    entry: plugin.path,
    output: `${cls}.dll`,
    installPath: "/opt/terraria-plugins",
    target: { terraria: TSHOCK_TARGET.terraria, loader: "TShock", loaderVersion: TSHOCK_TARGET.tshock, api: `TerrariaServerAPI ${TSHOCK_TARGET.tsapi}`, dotnet: TSHOCK_TARGET.dotnet },
    permissions,
    commands: body.commands.map((x) => `/${x}`),
  });
  const config = file(`${cls}.json`, JSON.stringify(settings.json, null, 2) + "\n");
  const test = file(
    `${cls}.SelfCheck.cs`,
    code`
      using TShockAPI;

      namespace Cyrus.${cls}
      {
          // Load-time self check (TShock plugins have no test runner): warns in the server log when a setting is
          // outside the range this plugin was balanced for. Call it from Initialize() after LoadSettings().
          internal static class SelfCheck
          {
              internal static void Run(${cls}Plugin.Settings s)
              {
                  if (s.Power > 3f)
                      TShock.Log.ConsoleWarn("[${s.name}] Power above 3 out-scales most vanilla gear.");
                  if (s.EffectTicks > 1200)
                      TShock.Log.ConsoleWarn("[${s.name}] Effects longer than 20 seconds feel permanent.");
                  if (s.RadiusTiles > 40)
                      TShock.Log.ConsoleWarn("[${s.name}] A radius over 40 tiles reaches off screen.");
              }
          }
      }`,
  );
  return { files: [plugin, csproj, man], config, test } as Built;
}

/* ═════════════════════════ entry points used by templates.ts ═════════════════════════ */

export function terrariaMod(input: TemplateInput): Built {
  return terrariaFlavor(input).flavor === "tshock" ? terrariaTShock(input) : terrariaTModLoader(input);
}

export function terrariaInstallSteps(input: TemplateInput): string[] {
  const { cls } = identity(input.modName);
  if (terrariaFlavor(input).flavor === "tshock") {
    return [
      `Build it: \`dotnet build -c Release\` (needs the free .NET 9 SDK). The plugin is \`bin/Release/${TSHOCK_TARGET.dotnet}/${cls}.dll\`.`,
      "On your Nxeon Terraria server, upload the .dll to `/opt/terraria-plugins` in Files, then restart the server.",
      `Check the console for \`${clean(input.modName, 60)} v${input.version}.0.0 initiated.\` and grant the permission (for example \`/group addperm default cyrus.${(identity(input.modName).snake.replace(/_/g, "").slice(0, 16) || "cyrus").toLowerCase()}.use\`). Players install nothing.`,
    ];
  }
  const mod = /Mod$/.test(cls) ? cls : `${cls}Mod`;
  return [
    "Install tModLoader (free on Steam for anyone who owns Terraria) and open Workshop → Develop Mods → Open Sources.",
    `Put this folder there named exactly \`${mod}\`, then click **Build + Reload** and enable it.`,
    "Multiplayer needs a tModLoader server (Nxeon Terraria servers run TShock today). Players who join get the mod sent to them automatically; tModLoader warns that it is not from the Workshop, and they accept it.",
  ];
}

/** Extra plain-language notes for the Explain/notes tab. */
export function terrariaNotes(input: TemplateInput): string[] {
  const f = terrariaFlavor(input);
  const out = [f.reason];
  if (f.flavor === "tshock") {
    out.push(`Built for TShock ${TSHOCK_TARGET.tshock} on Terraria ${TSHOCK_TARGET.terraria}, the version Nxeon Terraria servers run. Players must be on the same Terraria version to join.`);
    out.push("Server plugins can only use what the base game has: vanilla items, enemies, bosses and buffs. For brand-new items or bosses, ask for a tModLoader content mod.");
  } else {
    out.push(`Built for tModLoader ${TML_TARGET.month} stable (Terraria ${TML_TARGET.terraria}). tModLoader has not moved to 1.4.5 yet, so this mod cannot run on a 1.4.5 TShock server.`);
    out.push("Placeholder art is borrowed from the player's own game until you add your own PNGs; nothing is copied into the mod.");
  }
  const built = terrariaMod(input) as Built & { notes?: string[] };
  return [...out, ...(built.notes ?? [])];
}

/** Stable seed for callers that want to show which mode/kind was chosen (tests, Explain tab). */
export function terrariaPlan(input: TemplateInput): { flavor: TerrariaFlavor; kind: string } {
  const f = terrariaFlavor(input).flavor;
  if (f === "tshock") return { flavor: f, kind: `plugin:${tshockMode(input)}` };
  const k = input.category.key;
  const arch = ARCH[k];
  return { flavor: f, kind: `${arch}:${k === "weapons" || k === "magic" ? weaponKind(input) : k}:${hashStr(input.modName) % 1}` };
}

