/**
 * Static validator for Cyrus-generated Terraria mods (PURE, client-safe). Runs before a customer sees a build and
 * again before anything is installed. Two layers:
 *   1. the GameSupport `dangerousApis` (block/warn) and `knowledge.failureRules` (version breakages), on code with
 *      comments and string contents blanked so a comment or a chat message cannot trip or hide a rule;
 *   2. structural checks per flavour: manifest, build.txt/csproj, entry points, namespaces, textures, hook
 *      cleanup, ApiVersion, the TShock/tModLoader boundary, file-write paths and the files we refuse to ship.
 * A "block" issue means the build must not be offered; "warn" is shown to the creator and logged.
 */
import type { ModFile } from "@/lib/cyrus/types";
import support, { TML_TARGET, TSHOCK_TARGET, type TerrariaFlavor } from "./terraria";

export type TerrariaIssue = { severity: "block" | "warn"; rule: string; message: string; file?: string; line?: number };
export type TerrariaValidation = { ok: boolean; flavor: TerrariaFlavor | null; issues: TerrariaIssue[] };

/** Blank out comments and the inside of string/char literals, keeping line numbers and the quotes. */
export function stripCs(src: string): string {
  let out = "";
  let i = 0;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    const d = src[i + 1];
    if (c === "/" && d === "/") {
      while (i < n && src[i] !== "\n") (out += " "), i++;
    } else if (c === "/" && d === "*") {
      out += "  ";
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) (out += src[i] === "\n" ? "\n" : " "), i++;
      out += "  ";
      i += 2;
    } else if (c === '"' || (c === "@" && d === '"') || (c === "$" && d === '"') || (c === "$" && d === "@") || (c === "@" && d === "$")) {
      // regular, verbatim and interpolated strings: keep the quotes, blank the text (interpolation holes kept)
      const verbatim = src.slice(i, i + 3).includes("@");
      const interp = src.slice(i, i + 3).includes("$");
      while (src[i] !== '"') out += src[i++];
      out += '"';
      i++;
      let depth = 0;
      while (i < n) {
        const ch = src[i];
        if (interp && ch === "{" && src[i + 1] !== "{") {
          depth++;
          out += ch;
          i++;
          continue;
        }
        if (interp && depth > 0) {
          if (ch === "}") depth--;
          out += ch;
          i++;
          continue;
        }
        if (!verbatim && ch === "\\") {
          out += "  ";
          i += 2;
          continue;
        }
        if (ch === '"') {
          if (verbatim && src[i + 1] === '"') {
            out += "  ";
            i += 2;
            continue;
          }
          break;
        }
        out += ch === "\n" ? "\n" : " ";
        i++;
      }
      out += '"';
      i++;
    } else if (c === "'" && src[i + 2] === "'") {
      out += "' '";
      i += 3;
    } else if (c === "'" && d === "\\" && src[i + 3] === "'") {
      out += "'  '";
      i += 4;
    } else {
      out += c;
      i++;
    }
  }
  return out;
}

const lineOf = (src: string, index: number) => src.slice(0, index).split("\n").length;
const isCs = (f: ModFile) => f.path.endsWith(".cs");

function flavorOf(files: ModFile[], issues: TerrariaIssue[]): { flavor: TerrariaFlavor | null; manifest: Record<string, unknown> | null } {
  const m = files.find((f) => f.path === "cyrus.mod.json");
  const code = files.filter(isCs).map((f) => f.content).join("\n");
  const guess: TerrariaFlavor | null = /\bTerrariaPlugin\b/.test(code) ? "tshock" : /\bTerraria\.ModLoader\b/.test(code) || files.some((f) => f.path === "build.txt") ? "tmodloader" : null;
  if (!m) {
    issues.push({ severity: "block", rule: "manifest-missing", message: "cyrus.mod.json is missing: Cyrus cannot tell which server this mod is for." });
    return { flavor: guess, manifest: null };
  }
  let manifest: Record<string, unknown>;
  try {
    manifest = JSON.parse(m.content);
  } catch {
    issues.push({ severity: "block", rule: "manifest-json", message: "cyrus.mod.json is not valid JSON.", file: m.path });
    return { flavor: guess, manifest: null };
  }
  const flavor = manifest.flavor === "tshock" || manifest.flavor === "tmodloader" ? manifest.flavor : null;
  const need = (k: string, ok: boolean, msg: string) => ok || issues.push({ severity: "block", rule: `manifest-${k}`, message: msg, file: m.path });
  need("game", manifest.game === "terraria", "The manifest is not for Terraria.");
  need("flavor", !!flavor, 'The manifest must say flavor "tshock" or "tmodloader".');
  need("name", typeof manifest.name === "string" && !!(manifest.name as string).trim(), "The manifest needs a name.");
  need("internalName", typeof manifest.internalName === "string" && /^[A-Za-z][A-Za-z0-9]{1,63}$/.test(manifest.internalName as string), "internalName must be letters and digits only, starting with a letter.");
  need("version", typeof manifest.version === "string" && /^\d+(\.\d+){1,3}$/.test(manifest.version as string), "version must look like 1.0 or 1.0.0.");
  const target = (manifest.target ?? {}) as Record<string, string>;
  need("target", typeof target.terraria === "string" && typeof target.loaderVersion === "string", "The manifest must record the target Terraria and loader versions.");
  if (flavor && guess && flavor !== guess)
    issues.push({ severity: "block", rule: "flavor-mismatch", message: `The manifest says ${flavor} but the code is a ${guess === "tshock" ? "TShock plugin" : "tModLoader mod"}.`, file: m.path });
  if (flavor === "tshock") {
    need("side", manifest.side === "server" && manifest.playersInstall === false, "A TShock plugin is server-only: side must be server and playersInstall false.");
    if (target.loaderVersion && target.loaderVersion !== TSHOCK_TARGET.tshock)
      issues.push({ severity: "warn", rule: "tshock-version", message: `Built for TShock ${target.loaderVersion}; Nxeon servers now run ${TSHOCK_TARGET.tshock}. Rebuild before installing.`, file: m.path });
  }
  if (flavor === "tmodloader") {
    need("side", manifest.side === "both" || manifest.side === "client" || manifest.side === "server", "A tModLoader mod's side must be both, client or server.");
    if (target.terraria && !target.terraria.startsWith("1.4.4"))
      issues.push({ severity: "block", rule: "tml-terraria", message: `tModLoader stable is on Terraria ${TML_TARGET.terraria}; a ${target.terraria} target cannot be built yet.`, file: m.path });
  }
  if (typeof manifest.name === "string" && /terraria/i.test(manifest.name))
    issues.push({ severity: "warn", rule: "trademark", message: 'tModLoader\'s terms do not allow "Terraria" in a mod name. Use "for Terraria" in the description instead.', file: m.path });
  return { flavor: flavor ?? guess, manifest };
}

function fileSafety(files: ModFile[], issues: TerrariaIssue[]) {
  for (const f of files) {
    if (f.path.startsWith("/") || f.path.includes("..") || f.path.includes("\\") || /^[A-Za-z]:/.test(f.path))
      issues.push({ severity: "block", rule: "path", message: "Files must stay inside the mod folder.", file: f.path });
    if (/\.(dll|exe|so|dylib|bat|cmd|sh|ps1|tmod|pdb)$/i.test(f.path))
      issues.push({ severity: "block", rule: "binary", message: "Generated mods ship source only: no compiled or executable files.", file: f.path });
  }
}

function runPatterns(files: ModFile[], flavor: TerrariaFlavor | null, issues: TerrariaIssue[]) {
  const rules = support.knowledge?.failureRules ?? [];
  for (const f of files.filter(isCs)) {
    const code = stripCs(f.content);
    for (const d of support.dangerousApis) {
      const m = new RegExp(d.pattern).exec(code);
      if (m) issues.push({ severity: d.severity, rule: "dangerous-api", message: `${m[0].trim()}: ${d.why}`, file: f.path, line: lineOf(code, m.index) });
    }
    for (const r of rules) {
      if (r.id.startsWith("tml-") && flavor !== "tmodloader") continue;
      if (r.id.startsWith("tshock-") && flavor !== "tshock") continue;
      // Rules that look at string contents (paths) run on the raw source; everything else on stripped code.
      const m = new RegExp(r.detect).exec(r.id.endsWith("-path") ? f.content : code);
      if (m) issues.push({ severity: "block", rule: r.id, message: `${r.why} Fix: ${r.fix}`, file: f.path, line: lineOf(f.content, m.index) });
    }
  }
}

/** File writes must target the mod's own config/save folder. */
function writePaths(files: ModFile[], flavor: TerrariaFlavor | null, issues: TerrariaIssue[]) {
  const WRITE = /\b(File\.(WriteAllText|WriteAllBytes|AppendAllText|Create|OpenWrite|Open)|new\s+(StreamWriter|FileStream))\s*\(\s*([^,)]+)/g;
  for (const f of files.filter(isCs)) {
    const code = stripCs(f.content);
    for (const m of code.matchAll(WRITE)) {
      const arg = m[4].trim();
      const base = flavor === "tshock" ? "TShock\\.SavePath" : "Main\\.SavePath";
      const direct = new RegExp(base).test(arg);
      const viaProp = /^[A-Za-z_]\w*$/.test(arg) && new RegExp(`\\b${arg}\\s*(=>|=)\\s*Path\\.Combine\\(\\s*${base}`).test(code);
      if (!direct && !viaProp)
        issues.push({ severity: "block", rule: "write-path", message: `Writes to "${arg}", which is not inside ${flavor === "tshock" ? "TShock.SavePath" : "the tModLoader save folder"}.`, file: f.path, line: lineOf(code, m.index!) });
    }
  }
}

function tmlChecks(files: ModFile[], manifest: Record<string, unknown> | null, issues: TerrariaIssue[]) {
  const build = files.find((f) => f.path === "build.txt");
  if (!build) issues.push({ severity: "block", rule: "tml-build-txt", message: "build.txt is missing (tModLoader reads the name, version and side from it)." });
  else {
    const props = Object.fromEntries(build.content.split("\n").filter((l) => l.includes("=")).map((l) => [l.slice(0, l.indexOf("=")).trim(), l.slice(l.indexOf("=") + 1).trim()]));
    if (!props.displayName) issues.push({ severity: "warn", rule: "tml-display-name", message: "build.txt has no displayName.", file: build.path });
    if (!/^\d+(\.\d+){1,3}$/.test(props.version ?? "")) issues.push({ severity: "block", rule: "tml-version", message: "build.txt version must be 2 to 4 numbers like 1.0 or 1.2.3.4.", file: build.path });
    if (props.side && !/^(Both|Client|Server|NoSync)$/.test(props.side)) issues.push({ severity: "block", rule: "tml-side", message: "side must be Both, Client, Server or NoSync.", file: build.path });
    const side = (props.side || "Both").toLowerCase();
    if (manifest && typeof manifest.side === "string" && manifest.side !== (side === "nosync" ? "both" : side))
      issues.push({ severity: "block", rule: "tml-side-mismatch", message: `build.txt side (${props.side || "Both"}) does not match the manifest (${manifest.side}).`, file: build.path });
    if (manifest && props.version && manifest.version !== props.version)
      issues.push({ severity: "warn", rule: "tml-version-mismatch", message: "build.txt and cyrus.mod.json disagree on the version.", file: build.path });
  }
  const internal = typeof manifest?.internalName === "string" ? (manifest.internalName as string) : null;
  const cs = files.filter(isCs);
  if (!cs.length) issues.push({ severity: "block", rule: "tml-no-code", message: "No C# files: there is nothing to load." });
  let modClasses = 0;
  const pngs = new Set(files.filter((f) => f.path.endsWith(".png")).map((f) => f.path.replace(/\.png$/, "")));
  for (const f of cs) {
    const code = stripCs(f.content);
    for (const ns of code.matchAll(/\bnamespace\s+([\w.]+)/g)) {
      if (internal && !(ns[1] === internal || ns[1].startsWith(`${internal}.`)))
        issues.push({ severity: "block", rule: "tml-namespace", message: `Namespace ${ns[1]} must start with the mod's name ${internal}, or tModLoader refuses to build it.`, file: f.path, line: lineOf(code, ns.index!) });
    }
    modClasses += (code.match(/class\s+\w+\s*:\s*Mod\b(?!\w)/g) ?? []).length;
    // Content that tModLoader autoloads a texture for must have one: a Texture override or a PNG named after the class.
    const nsName = /\bnamespace\s+([\w.]+)/.exec(code)?.[1] ?? "";
    for (const m of code.matchAll(/class\s+(\w+)\s*:\s*(ModItem|ModNPC|ModProjectile|ModBuff|ModTile|ModWall|ModDust)\b/g)) {
      const body = code.slice(m.index!, nextClass(code, m.index! + 1));
      const hasOverride = /override\s+string\s+Texture\s*=>/.test(body);
      const pngPath = `${nsName.split(".").slice(1).join("/")}/${m[1]}`.replace(/^\//, "");
      if (!hasOverride && !pngs.has(pngPath))
        issues.push({ severity: "block", rule: "tml-texture", message: `${m[1]} (${m[2]}) has no texture: add ${pngPath}.png or a Texture override, or the mod will not load.`, file: f.path, line: lineOf(code, m.index!) });
    }
    if (/\bNPC\.NewNPC\s*\(/.test(code) && !/NetmodeID\.MultiplayerClient|Main\.netMode\s*!=\s*1|Main\.netMode\s*==\s*NetmodeID\.Server/.test(code))
      issues.push({ severity: "warn", rule: "tml-mp-spawn", message: "Spawns enemies without a multiplayer check: in multiplayer only the server may spawn them.", file: f.path });
  }
  if (modClasses > 1) issues.push({ severity: "block", rule: "tml-mod-class", message: "Only one class may extend Mod." });
}

const nextClass = (code: string, from: number) => {
  const i = code.slice(from).search(/\bclass\s+\w+/);
  return i < 0 ? code.length : from + i;
};

function tshockChecks(files: ModFile[], issues: TerrariaIssue[]) {
  const cs = files.filter(isCs);
  const all = cs.map((f) => stripCs(f.content)).join("\n");
  const main = cs.find((f) => /\bclass\s+\w+\s*:\s*TerrariaPlugin\b/.test(stripCs(f.content)));
  if (!main) {
    issues.push({ severity: "block", rule: "tshock-entry", message: "No class extends TerrariaPlugin: TShock will not load anything." });
    return;
  }
  const code = stripCs(main.content);
  const api = /\[ApiVersion\(\s*(\d+)\s*,\s*(\d+)\s*\)\]/.exec(code);
  if (!api) issues.push({ severity: "block", rule: "tshock-apiversion", message: "Missing [ApiVersion(2, 1)]: TShock skips plugins without it.", file: main.path });
  else if (`${api[1]}.${api[2]}` !== TSHOCK_TARGET.tsapi)
    issues.push({ severity: "block", rule: "tshock-apiversion", message: `[ApiVersion(${api[1]}, ${api[2]})] does not match TerrariaServerAPI ${TSHOCK_TARGET.tsapi}; TShock would ignore the plugin.`, file: main.path });
  if (!/\(\s*Main\s+\w+\s*\)\s*:\s*base\s*\(\s*\w+\s*\)/.test(code))
    issues.push({ severity: "block", rule: "tshock-ctor", message: "The plugin needs a constructor taking (Main game) : base(game); TShock creates it that way.", file: main.path });
  if (!/override\s+void\s+Initialize\s*\(/.test(code)) issues.push({ severity: "block", rule: "tshock-initialize", message: "The plugin needs Initialize().", file: main.path });
  // Every hook registered must be released in Dispose, or a reload leaves ghost handlers behind.
  for (const m of all.matchAll(/ServerApi\.Hooks\.(\w+)\.Register\s*\(\s*this\s*,\s*(\w+)/g)) {
    if (!new RegExp(`ServerApi\\.Hooks\\.${m[1]}\\.Deregister\\s*\\(\\s*this\\s*,\\s*${m[2]}`).test(all))
      issues.push({ severity: "block", rule: "tshock-deregister", message: `${m[1]} is registered but never deregistered in Dispose.`, file: main.path });
  }
  for (const m of all.matchAll(/(\w+(?:\.\w+)*)\s*\+=\s*(\w+)\s*;/g)) {
    if (/Hooks\./.test(m[1]) && !new RegExp(`${m[1].replace(/\./g, "\\.")}\\s*-=\\s*${m[2]}`).test(all))
      issues.push({ severity: "block", rule: "tshock-unsubscribe", message: `${m[1]} += ${m[2]} has no matching -= in Dispose.`, file: main.path });
  }
  if (/Commands\.ChatCommands\.Add\s*\(/.test(all) && !/Commands\.ChatCommands\.(RemoveAll|Remove)\s*\(/.test(all))
    issues.push({ severity: "warn", rule: "tshock-commands", message: "Commands are added but never removed on Dispose.", file: main.path });
  if (/new\s+Command\s*\(\s*(\w+\s*,|"\s*"\s*,)?\s*\w+\s*,\s*"/.test(all) && /new\s+Command\s*\(\s*\w+\s*,\s*"/.test(all.replace(/new\s+Command\s*\(\s*(UsePermission|AdminPermission|"[^"]*")\s*,/g, "")))
    issues.push({ severity: "warn", rule: "tshock-permission", message: "A command is registered without a permission: anyone could run it.", file: main.path });
  const csproj = files.find((f) => f.path.endsWith(".csproj"));
  if (csproj) {
    const tfm = /<TargetFramework>([^<]+)<\/TargetFramework>/.exec(csproj.content)?.[1];
    if (tfm && tfm !== TSHOCK_TARGET.dotnet) issues.push({ severity: "block", rule: "tshock-tfm", message: `TShock ${TSHOCK_TARGET.tshock} runs on ${TSHOCK_TARGET.dotnet}; this project targets ${tfm}.`, file: csproj.path });
    const ver = /Include="TShock"\s+Version="([^"]+)"/.exec(csproj.content)?.[1];
    if (!ver) issues.push({ severity: "warn", rule: "tshock-reference", message: "The project does not reference the TShock package.", file: csproj.path });
    else if (ver !== TSHOCK_TARGET.tshock) issues.push({ severity: "warn", rule: "tshock-reference", message: `References TShock ${ver}; Nxeon servers run ${TSHOCK_TARGET.tshock}.`, file: csproj.path });
  }
}

export function validateTerraria(files: ModFile[]): TerrariaValidation {
  const issues: TerrariaIssue[] = [];
  const { flavor, manifest } = flavorOf(files, issues);
  fileSafety(files, issues);
  runPatterns(files, flavor, issues);
  writePaths(files, flavor, issues);
  if (flavor === "tmodloader") tmlChecks(files, manifest, issues);
  if (flavor === "tshock") tshockChecks(files, issues);
  return { ok: !issues.some((i) => i.severity === "block"), flavor, issues };
}

