const input = (category: CategoryKey, prompt: string, modName: string, model: ModelId = "saka", version = 1) => ({ game, category: CATEGORY_BY_KEY[category], modName, prompt, model, version });
const replace = (files: ModFile[], path: string, fn: (s: string) => string) => files.map((f) => (f.path === path ? { ...f, content: fn(f.content) } : f));
const rules = (files: ModFile[]) => validateTerraria(files).issues.map((i) => i.rule);

describe("terraria GameSupport", () => {
  it("is well formed and honest", () => {
    assert.equal(support.id, "terraria");
    assert.equal(support.language, "C#");
    assert.ok(support.sources.length >= 10 && support.sources.every((s) => s.startsWith("https://")));
    assert.ok(support.unknowns.length >= 3);
    assert.equal(support.verification.canRunSandbox, false, "no live load-test exists yet");
    for (const d of support.dangerousApis) assert.doesNotThrow(() => new RegExp(d.pattern), d.pattern);
    for (const r of support.knowledge!.failureRules) {
      assert.doesNotThrow(() => new RegExp(r.detect), r.id);
      assert.match(r.id, /^(tml|tshock)-/);
    }
    for (const c of support.categories) assert.ok(CATEGORY_BY_KEY[c as CategoryKey], c);
  });

  it("targets exactly the TShock release Nxeon servers are pinned to", () => {
    const k = terrariaKnown(TERRARIA_PINNED_VERSION)!;
    assert.equal(TSHOCK_TARGET.tshock, TERRARIA_PINNED_VERSION);
    assert.equal(TSHOCK_TARGET.terraria, k.terraria);
    // If the platform moves to a new TShock major, this table needs the new TerrariaServerAPI/.NET facts first.
    assert.ok(TSHOCK_LINES[Number(TERRARIA_PINNED_VERSION.split(".")[0])], "add a TSHOCK_LINES row for the new TShock major");
    assert.ok(support.versions.some((v) => v.status === "current" && v.version.includes(k.terraria)));
  });

  it("keeps tModLoader on 1.4.4 stable and lists 1.4.3 + 1.4.5 honestly", () => {
    assert.match(TML_TARGET.terraria, /^1\.4\.4/);
    const v = support.versions.map((x) => `${x.status}:${x.version}`).join("|");
    assert.match(v, /legacy:Terraria 1\.4\.3/);
    assert.match(v, /unsupported:Terraria 1\.4\.5 \(tModLoader/);
  });
});

describe("terraria flavour routing", () => {
  const cases: [CategoryKey, string, "tshock" | "tmodloader"][] = [
    ["weapons", "a frost sword that chills enemies", "tmodloader"],
    ["creatures", "a moth boss with three phases", "tmodloader"],
    ["items", "gravity boots accessory", "tmodloader"],
    ["mechanics", "a /heal command with a cooldown", "tshock"],
    ["mechanics", "welcome players and give a starter kit", "tshock"],
    ["quests", "reward everyone when a boss dies", "tshock"],
    ["quests", "boss rush that spawns bosses one after another", "tshock"],
    ["weapons", "tshock server plugin: swords chain lightning", "tshock"],
    ["mechanics", "a tmodloader perk that makes you glow", "tmodloader"],
    ["interface", "a hud overlay", "tmodloader"],
    ["shaders", "a night screen tint", "tmodloader"],
    ["mechanics", "vanilla players, nothing to install: auto broadcast tips", "tshock"],
  ];
  for (const [cat, prompt, want] of cases) {
    it(`${prompt} -> ${want}`, () => assert.equal(terrariaFlavor(input(cat, prompt, "Test Mod")).flavor, want));
  }
});

describe("terraria generator output (whole matrix, all models)", () => {
  const models: ModelId[] = ["katara", "saka", "yakko"];
  for (const row of TERRARIA_MATRIX) {
    for (const model of models) {
      it(`${row.name} / ${model} passes the validator`, () => {
        const inp = input(row.category, row.prompt, row.name, model, model === "yakko" ? 2 : 1);
        const files = buildModFiles(inp);
        const v = validateTerraria(files);
        assert.deepEqual(v.issues.filter((i) => i.severity === "block"), [], JSON.stringify(v.issues, null, 1));
        assert.equal(v.flavor, terrariaPlan(inp).flavor);
        const man = JSON.parse(files.find((f) => f.path === "cyrus.mod.json")!.content);
        assert.equal(man.game, "terraria");
        if (man.flavor === "tshock") {
          assert.equal(man.target.loaderVersion, TSHOCK_TARGET.tshock);
          assert.equal(man.playersInstall, false);
        } else {
          assert.equal(man.target.loaderVersion, TML_TARGET.month);
          assert.ok(files.some((f) => f.path === "build.txt"));
        }
        // Katara ships three files and they must be a complete project on their own.
        if (model === "katara") assert.equal(files.length, 3);
        // No warnings from the danger list on our own output.
        assert.deepEqual(v.issues.filter((i) => i.rule === "dangerous-api"), []);
      });
    }
  }

  it("is deterministic", () => {
    const a = buildModFiles(input("weapons", "a frost sword", "Frost Edge"));
    const b = buildModFiles(input("weapons", "a frost sword", "Frost Edge"));
    assert.deepEqual(a, b);
  });

  it("plugins keep config under TShock.SavePath and guard re-entrant strikes", () => {
    const plugin = buildModFiles(input("weapons", "tshock server plugin: swords chain lightning", "Storm Edge"))[0].content;
    assert.match(plugin, /Path\.Combine\(TShock\.SavePath/);
    assert.match(plugin, /\[ApiVersion\(2, 1\)\]/);
    assert.match(plugin, /if \(applying\)/);
    assert.match(plugin, /NpcStrike\.Deregister\(this, OnStrike\)/);
  });

  it("content uses the player's own game art instead of shipping images", () => {
    const files = buildModFiles(input("creatures", "a moth-king boss", "Hollow Monarch"));
    assert.ok(!files.some((f) => /\.(png|dll|exe)$/.test(f.path)));
    assert.match(files[0].content, /Texture => \$"Terraria\/Images\/NPC_/);
    assert.match(files[0].content, /NetmodeID\.MultiplayerClient/);
  });

  it("install steps and notes say which server the mod needs", () => {
    const ts = input("mechanics", "a /heal command", "Heal Pulse");
    assert.match(terrariaInstallSteps(ts).join(" "), /\/opt\/terraria-plugins/);
    assert.match(buildModNotes(ts), /server plugin/);
    const tml = input("weapons", "a frost sword", "Frost Edge");
    assert.match(terrariaInstallSteps(tml).join(" "), /tModLoader server/);
    assert.match(buildModNotes(tml), /1\.4\.5/);
  });
});

describe("terraria validator catches broken or harmful mods", () => {
  const tml = () => buildModFiles(input("weapons", "a frost sword", "Frost Edge"));
  const ts = () => buildModFiles(input("mechanics", "a /frostnova command", "Frost Nova"));

  it("blocks process, network, native and save-wiping code", () => {
    for (const bad of [
      'System.Diagnostics.Process.Start("calc");',
      "var c = new System.Net.Http.HttpClient();",
      '[DllImport("x")] static extern void X();',
      'System.IO.File.Delete(Main.WorldPath);',
      "while (true) { }",
      "System.Threading.Thread.Sleep(1000);",
      'Assembly.Load(bytes);',
    ]) {
      const files = replace(tml(), tml()[0].path, (s) => s.replace("public override void SetDefaults() {", `public override void SetDefaults() {\n${bad}`));
      const v = validateTerraria(files);
      assert.equal(v.ok, false, bad);
    }
  });

  it("ignores dangerous words inside comments and strings", () => {
    const files = replace(tml(), tml()[0].path, (s) => s.replace("public override void SetDefaults() {", 'public override void SetDefaults() {\n// Process.Start is not used here\nstring tip = "never call File.Delete";'));
    assert.equal(validateTerraria(files).ok, true, JSON.stringify(validateTerraria(files).issues));
  });

  it("catches 1.4.3-era tModLoader APIs", () => {
    const files = replace(tml(), tml()[0].path, (s) => s.replace("public override void SetDefaults() {", 'public override void SetStaticDefaults() { DisplayName.SetDefault("x"); }\npublic override void SetDefaults() {'));
    assert.ok(rules(files).includes("tml-143-setdefault"));
    const old = replace(tml(), tml()[0].path, (s) => s.replace("NPC.HitInfo hit, int damageDone", "int damage, float knockback, bool crit"));
    assert.ok(rules(old).includes("tml-143-onhitnpc"));
  });

  it("refuses to mix TShock and tModLoader", () => {
    const files = replace(ts(), ts()[0].path, (s) => s.replace("using TShockAPI;", "using TShockAPI;\nusing Terraria.ModLoader;"));
    assert.ok(rules(files).includes("tshock-tml-api"));
    const other = replace(tml(), tml()[0].path, (s) => s.replace("using Terraria;", "using Terraria;\nusing TShockAPI;"));
    assert.ok(rules(other).includes("tml-tshock-api"));
  });

  it("checks TShock structure: ApiVersion, Dispose, paths, target", () => {
    assert.ok(rules(replace(ts(), ts()[0].path, (s) => s.replace("[ApiVersion(2, 1)]", "[ApiVersion(1, 25)]"))).includes("tshock-apiversion"));
    assert.ok(rules(replace(ts(), ts()[0].path, (s) => s.replace("ServerApi.Hooks.ServerLeave.Deregister(this, OnLeave);", ""))).includes("tshock-deregister"));
    assert.ok(rules(replace(ts(), ts()[0].path, (s) => s.replace("Path.Combine(TShock.SavePath, ", 'Path.Combine("tshock/", '))).includes("tshock-hardcoded-path"));
    assert.ok(rules(replace(ts(), ts()[0].path, (s) => s.replace("private void LoadSettings()\n", 'private void Evil() { File.WriteAllText("/etc/passwd", "x"); }\nprivate void LoadSettings()\n'))).includes("write-path"));
    assert.ok(rules(replace(ts(), ts()[1].path, (s) => s.replace("net9.0", "net6.0"))).includes("tshock-tfm"));
  });

  it("checks tModLoader structure: manifest, namespace, textures, side", () => {
    assert.ok(rules(tml().filter((f) => f.path !== "cyrus.mod.json")).includes("manifest-missing"));
    assert.ok(rules(replace(tml(), tml()[0].path, (s) => s.replace(/namespace \w+\.Content/, "namespace Other.Content"))).includes("tml-namespace"));
    assert.ok(rules(replace(tml(), tml()[0].path, (s) => s.replace(/public override string Texture => .*\n/, ""))).includes("tml-texture"));
    assert.ok(rules(replace(tml(), "build.txt", (s) => s.replace("side = Both", "side = Client"))).includes("tml-side-mismatch"));
    assert.ok(rules(replace(tml(), "cyrus.mod.json", (s) => s.replace('"name": "Frost Edge"', '"name": "Terraria Frost Edge"'))).includes("trademark"));
    assert.ok(rules([...tml(), { path: "lib/evil.dll", language: "text", content: "" }]).includes("binary"));
    assert.ok(rules([...tml(), { path: "../outside.cs", language: "csharp", content: "" }]).includes("path"));
  });

  it("stripCs keeps line numbers and interpolation holes", () => {
    const src = 'var a = $"x {Process.Start()} y"; // Process\n/* File.Delete */ b();';
    const out = stripCs(src);
    assert.equal(out.split("\n").length, 2);
    assert.match(out, /Process\.Start/);
    assert.doesNotMatch(out, /File\.Delete/);
  });
});

